declare
  v_ngo public.ngo_profiles%rowtype;
  v_node text;
  v_dist double precision;
  v_prev text;
  v_new text;
  v_eligible integer;
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and session_user not in ('postgres', 'supabase_admin') then
    raise exception 'TRUSTED_VERIFIER_ONLY';
  end if;
  if p_ngo is null or p_verified is null then raise exception 'NGO_AND_DECISION_REQUIRED'; end if;
  if nullif(btrim(p_reason), '') is null then raise exception 'VERIFICATION_REASON_REQUIRED'; end if;

  select * into v_ngo from public.ngo_profiles where user_id = p_ngo for update;
  if not found then raise exception 'NGO_NOT_FOUND'; end if;
  v_prev := case when v_ngo.location_verified_at is null then 'UNVERIFIED' else 'VERIFIED' end;

  if p_verified then
    select node_id, snap_distance_m into v_node, v_dist
      from public.geolock_resolve_road_node(v_ngo.latitude, v_ngo.longitude);
    if v_node is null then raise exception 'NGO_LOCATION_NOT_ROUTABLE'; end if;
  end if;
  v_new := case when p_verified then 'VERIFIED' else 'UNVERIFIED' end;

  update public.ngo_profiles
     set location_verified_at = case when p_verified then clock_timestamp() end,
         road_node_id = v_node
   where user_id = p_ngo;
  update public.vehicles set depot_road_node_id = null where ngo_user_id = p_ngo;

  perform public.geolock_refresh_ngo_road_eligibility(p_ngo);
  select count(*) into v_eligible from public.ngo_listing_road_eligibility
   where ngo_user_id = p_ngo and outcome = 'ELIGIBLE';

  insert into public.audit_events(actor_user_id, actor_role, entity_type, entity_id,
    event_type, request_id, previous_state, requested_state, resulting_state,
    reason_code, outcome, details)
  values (null, 'SYSTEM', 'NGO', p_ngo, 'VERIFY_NGO_LOCATION', gen_random_uuid(),
    v_prev, v_new, v_new, p_reason, 'SUCCESS',
    jsonb_build_object('road_node_id', v_node,
                       'snap_distance_m', round(v_dist::numeric, 1),
                       'eligible_open_listings', v_eligible));

  return jsonb_build_object('ngo_user_id', p_ngo, 'location_status', v_new,
    'road_node_id', v_node, 'snap_distance_m', round(v_dist::numeric, 1),
    'eligible_open_listings', v_eligible);
end

declare v_snapshot text;
begin
  if tg_op='UPDATE' then
    if new.eligibility_generation=old.eligibility_generation then return null; end if;
  end if;
  delete from public.ngo_listing_road_eligibility where listing_id=new.listing_id;
  -- Do not lock old queue rows here: workers lock queue before listing, while
  -- this trigger already holds listing. Workers supersede old generations.
  if new.listing_status='AVAILABLE' then
    select c.network_snapshot_id into v_snapshot from public.road_network_coverage c
     where c.active_flag and c.dataset_kind='OPERATIONAL' and c.approved_at is not null
       and c.max_snap_distance_m=500 for share;
    if v_snapshot is null then raise exception 'OPERATIONAL_ROAD_COVERAGE_UNAVAILABLE'; end if;
    insert into public.listing_eligibility_refresh_jobs(
      listing_id,eligibility_generation,expected_road_node_id,expected_snapshot_id)
    values(new.listing_id,new.eligibility_generation,new.pickup_road_node_id,v_snapshot);
  end if;
  return null;
end;

declare
  v_user uuid := auth.uid();
  v_road_node_resolution boolean := false;
  v_config_version text;
begin
  if v_user is null then
    raise exception 'UNAUTHENTICATED';
  end if;

  if to_regclass('public.road_network_nodes') is not null
     and to_regclass('public.road_network_coverage') is not null then
    begin
      execute $query$
        select exists (
          select 1
          from public.road_network_nodes as n
          join public.road_network_coverage as c using (network_snapshot_id)
          where n.active_flag
            and c.active_flag
            and c.dataset_kind = 'OPERATIONAL'
            and c.approved_at is not null
            and extensions.st_covers(
              c.coverage_area,
              extensions.st_setsrid(
                extensions.st_makepoint(n.longitude, n.latitude), 4326
              )
            )
        )
      $query$
      into v_road_node_resolution;
    exception
      when undefined_table or undefined_column or undefined_function then
        v_road_node_resolution := false;
    end;
  end if;

  select c.config_version
    into v_config_version
    from public.coordination_config as c
   where c.singleton;

  return jsonb_build_object(
    'ngo_location_registration', 'AUTO_VALIDATED',
    'location_picker', 'GOOGLE_MAPS',
    'road_node_resolution', v_road_node_resolution,
    'configuration_version', v_config_version
  );
end;

declare
  v_user uuid := auth.uid();
  v_ngo public.ngo_profiles%rowtype;
  v_snapshot text;
  v_node text;
  v_snap_distance double precision;
  v_resolved_snapshot text;
  v_generation bigint;
begin
  if v_user is null then raise exception 'UNAUTHENTICATED'; end if;
  if nullif(btrim(p_operating_address),'') is null
     or p_latitude is null or p_longitude is null
     or p_latitude not between -90 and 90
     or p_longitude not between -180 and 180 then
    raise exception 'INVALID_NGO_LOCATION';
  end if;

  -- Keep the approved snapshot fixed through validation, invalidation and enqueue.
  select c.network_snapshot_id into v_snapshot
    from public.road_network_coverage c
   where c.active_flag and c.dataset_kind='OPERATIONAL'
     and c.approved_at is not null and c.max_snap_distance_m=500
   for share;
  if v_snapshot is null then raise exception 'OPERATIONAL_ROAD_COVERAGE_UNAVAILABLE'; end if;

  select * into v_ngo from public.ngo_profiles n
   where n.user_id=v_user and n.active_flag for update;
  if not found then raise exception 'ACTIVE_NGO_PROFILE_REQUIRED'; end if;

  if exists(
    select 1 from public.donation_claims c
     where c.ngo_user_id=v_user and (
       c.claim_status in ('ACTIVE','RECONCILIATION_REQUIRED')
       or exists(select 1 from public.claim_leases le
                  where le.claim_id=c.claim_id
                    and le.lease_status in ('ACTIVE','RECONCILIATION_REQUIRED'))
       or not exists(select 1 from public.claim_leases le where le.claim_id=c.claim_id
          and ((c.claim_status='COMPLETED' and le.lease_status='COMPLETED')
            or (c.claim_status in ('RELEASED','EXPIRED','CANCELLED')
                and le.lease_status in ('RELEASED','EXPIRED'))))
     )
  ) then raise exception 'NGO_HAS_ACTIVE_OR_UNRESOLVED_CLAIMS'; end if;

  select r.node_id,r.snap_distance_m,r.snapshot_id
    into v_node,v_snap_distance,v_resolved_snapshot
    from public.geolock_resolve_road_node(p_latitude,p_longitude) r;
  if v_node is null or v_snap_distance is null or v_snap_distance < 0
     or v_snap_distance > 500 or v_resolved_snapshot is distinct from v_snapshot then
    raise exception 'NGO_LOCATION_NOT_ROUTABLE';
  end if;

  v_generation := v_ngo.location_generation + 1;
  update public.ngo_profiles set operating_address=btrim(p_operating_address),
    latitude=p_latitude,longitude=p_longitude,road_node_id=v_node,
    location_verified_at=clock_timestamp(),location_generation=v_generation
   where user_id=v_user;
  -- Existing trigger derives vehicle depots from the trusted NGO node.
  update public.vehicles set depot_road_node_id=null where ngo_user_id=v_user;

  -- Remove every prior result before committing the new location generation.
  delete from public.ngo_listing_road_eligibility where ngo_user_id=v_user;
  insert into public.ngo_eligibility_refresh_jobs(
    ngo_user_id,location_generation,expected_road_node_id,expected_snapshot_id)
  values(v_user,v_generation,v_node,v_snapshot);

  insert into public.audit_events(actor_user_id,actor_role,entity_type,entity_id,
    event_type,request_id,correlation_id,previous_state,requested_state,
    resulting_state,reason_code,outcome,details)
  values(v_user,'NGO','NGO',v_user,'SET_NGO_OPERATING_LOCATION',gen_random_uuid(),
    gen_random_uuid(),case when v_ngo.location_verified_at is null then 'INCOMPLETE' else 'VERIFIED' end,
    'VERIFIED','ELIGIBILITY_PENDING','SERVER_ROAD_NODE_VALIDATION','SUCCESS',
    jsonb_build_object('network_snapshot_id',v_snapshot,'road_node_id',v_node,
      'snap_distance_m',round(v_snap_distance::numeric,1),
      'location_generation',v_generation));

  return jsonb_build_object('location_status','VERIFIED','eligibility_status','PENDING',
    'road_node_id',v_node,'snap_distance_m',round(v_snap_distance::numeric,1),
    'network_snapshot_id',v_snapshot,'location_generation',v_generation);
end;

declare v_hubs integer; v_listings integer; v_donations integer; v_ngos integer := 0;
  v_rows integer; r record;
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and session_user not in ('postgres', 'supabase_admin') then
    raise exception 'TRUSTED_OPERATOR_ONLY';
  end if;

  update public.community_hubs set road_node_id = null;   -- trigger re-resolves
  get diagnostics v_hubs = row_count;

  update public.donations d
     set pickup_road_node_id = r2.node_id
    from public.donations d2
    left join lateral public.geolock_resolve_road_node(d2.latitude, d2.longitude) r2 on true
   where d.donation_id = d2.donation_id
     -- READY_FOR_PICKUP previously included claimed direct donations. Tasks
     -- retain their listing-node snapshot; do not rewrite tasks or route stops.
     and (d.donation_status in ('SUBMITTED','AVAILABLE','HUB_ASSIGNED')
       or (d.donation_status='CLAIMED' and d.collection_path='DIRECT_PICKUP'))
     and d.pickup_road_node_id is distinct from r2.node_id;
  get diagnostics v_donations = row_count;

  update public.listings l
     set pickup_road_node_id = r2.node_id
    from public.listings l2
    left join lateral public.geolock_resolve_road_node(l2.pickup_latitude, l2.pickup_longitude) r2 on true
   where l.listing_id = l2.listing_id
     and l.listing_status = 'AVAILABLE'
     and l.pickup_road_node_id is distinct from r2.node_id;
  get diagnostics v_listings = row_count;

  -- Re-check verified NGOs against the new snapshot (verification is kept only
  -- if the stored location still snaps within 500 m).
  for r in select n.user_id, n.latitude, n.longitude from public.ngo_profiles n
            where n.location_verified_at is not null loop
    update public.ngo_profiles
       set road_node_id = (select x.node_id from public.geolock_resolve_road_node(r.latitude, r.longitude) x)
     where user_id = r.user_id;
    update public.vehicles set depot_road_node_id = null where ngo_user_id = r.user_id;
    perform public.geolock_refresh_ngo_road_eligibility(r.user_id);
    v_ngos := v_ngos + 1;
  end loop;
  select count(*) into v_rows from public.ngo_listing_road_eligibility;

  return jsonb_build_object('hubs_rechecked', v_hubs, 'donations_changed', v_donations,
    'listings_changed', v_listings, 'ngos_rechecked', v_ngos, 'eligibility_rows', v_rows);
end

