declare
  v_user uuid := auth.uid();
begin
  if v_user is null then raise exception 'UNAUTHENTICATED'; end if;
  if p_role is null or p_role not in ('DONOR','NGO','HUB_ADMIN') then
    raise exception 'ROLE_NOT_SELF_SERVICE';
  end if;
  if nullif(btrim(p_full_name),'') is null then raise exception 'FULL_NAME_REQUIRED'; end if;
  if p_role='NGO' and nullif(btrim(p_ngo_name),'') is null then
    raise exception 'NGO_NAME_REQUIRED';
  end if;
  if exists(select 1 from public.user_profiles u where u.user_id=v_user) then
    raise exception 'ROLE_ALREADY_REGISTERED';
  end if;

  insert into public.user_profiles(user_id,full_name,phone_number,role)
  values(v_user,btrim(p_full_name),nullif(btrim(p_phone),''),p_role);

  if p_role='DONOR' then
    insert into public.donor_profiles(user_id) values(v_user);
  elsif p_role='NGO' then
    insert into public.ngo_profiles(user_id,ngo_name,registration_number)
    values(v_user,btrim(p_ngo_name),nullif(btrim(p_registration_number),''));
  else
    insert into public.hub_admin_profiles(user_id) values(v_user);
  end if;

  insert into public.audit_events(
    actor_user_id,actor_role,entity_type,entity_id,event_type,
    requested_state,resulting_state,reason_code,outcome,details
  ) values(
    v_user,p_role,'USER',v_user,'REGISTER_ROLE',p_role,p_role,
    case p_role when 'NGO' then 'NGO_LOCATION_SETUP_REQUIRED'
                when 'HUB_ADMIN' then 'HUB_SETUP_REQUIRED' end,
    'SUCCESS',jsonb_build_object('location_supplied_during_signup',false)
  );
  return v_user;
end;

declare v_user uuid:=auth.uid(); v_role text;
begin
  if v_user is null then raise exception 'UNAUTHENTICATED'; end if;
  if nullif(btrim(p_full_name),'') is null then raise exception 'FULL_NAME_REQUIRED'; end if;
  select role into v_role from public.user_profiles where user_id=v_user for update;
  if not found then raise exception 'PROFILE_NOT_FOUND'; end if;
  update public.user_profiles set full_name=btrim(p_full_name),phone_number=nullif(btrim(p_phone),'')
    where user_id=v_user;
  if v_role='NGO' then
    if nullif(btrim(p_ngo_name),'') is null then raise exception 'NGO_NAME_REQUIRED'; end if;
    update public.ngo_profiles set ngo_name=btrim(p_ngo_name),
      registration_number=nullif(btrim(p_registration_number),'') where user_id=v_user;
  end if;
  insert into public.audit_events(actor_user_id,actor_role,entity_type,entity_id,
    event_type,request_id,requested_state,resulting_state,outcome)
  values(v_user,v_role,'USER',v_user,'UPDATE_PROFILE',gen_random_uuid(),v_role,v_role,'SUCCESS');
  return jsonb_build_object('user_id',v_user,'role',v_role,'updated',true);
end;

declare v_job public.listing_eligibility_refresh_jobs%rowtype;
  v_listing public.listings%rowtype; v_snapshot text; v_state text;
  v_ngos uuid[];
begin
  if session_user<>'postgres' then raise exception 'TRUSTED_CRON_ONLY'; end if;
  select * into v_job from public.listing_eligibility_refresh_jobs j
   where j.job_status in ('PENDING','FAILED') and j.attempt_count<3
   order by j.requested_at,j.job_id limit 1 for update skip locked;
  if not found then return jsonb_build_object('processed',false); end if;
  update public.listing_eligibility_refresh_jobs set job_status='PROCESSING',
    attempt_count=attempt_count+1,started_at=clock_timestamp(),last_error_code=null
   where job_id=v_job.job_id;
  begin
    select c.network_snapshot_id into v_snapshot from public.road_network_coverage c
     where c.active_flag and c.dataset_kind='OPERATIONAL' and c.approved_at is not null
       and c.max_snap_distance_m=500 for share;

    -- Same profile-before-listing order as claim_listing. FOR SHARE conflicts
    -- with NGO worker/location UPDATE locks (FOR KEY SHARE would NOT suffice).
    -- Capture all profiles, including incomplete ones; retry on phantom inserts.
    select coalesce(array_agg(locked.user_id),'{}'::uuid[]) into v_ngos from (
      select n.user_id from public.ngo_profiles n order by n.user_id for share
    ) locked;
    select * into v_listing from public.listings where listing_id=v_job.listing_id for update;
    if not found or v_listing.listing_status<>'AVAILABLE'
       or v_listing.eligibility_generation<>v_job.eligibility_generation
       or v_listing.pickup_road_node_id is distinct from v_job.expected_road_node_id then
      update public.listing_eligibility_refresh_jobs set job_status='SUPERSEDED',
        completed_at=clock_timestamp(),last_error_code='LISTING_CHANGED' where job_id=v_job.job_id;
      return jsonb_build_object('processed',true,'outcome','SUPERSEDED');
    end if;
    if v_snapshot is null or v_snapshot is distinct from v_job.expected_snapshot_id then
      raise exception 'ROAD_SNAPSHOT_CHANGED';
    end if;

    perform public.geolock_refresh_listing_road_eligibility(v_job.listing_id);
    -- A new profile might have entered the refresh statement without a row lock.
    -- Roll back this refresh and retry, rather than delete a concurrently valid
    -- result produced by that NGO's own worker or publish an unprotected result.
    if exists(select 1 from public.ngo_profiles n where not (n.user_id=any(v_ngos))) then
      raise exception 'NGO_SET_CHANGED_RETRY';
    end if;
    if exists(select 1 from public.ngo_listing_road_eligibility e
      join public.ngo_profiles n on n.user_id=e.ngo_user_id
      join public.coordination_config cfg on cfg.singleton
      where e.listing_id=v_job.listing_id and
        (e.network_snapshot_id is distinct from v_snapshot
         or e.listing_road_node_id is distinct from v_job.expected_road_node_id
         or e.ngo_road_node_id is distinct from n.road_node_id
         or e.geofence_radius_m is distinct from cfg.geofence_radius_m)) then
      raise exception 'REFRESH_RESULT_MISMATCH';
    end if;
    update public.listing_eligibility_refresh_jobs set job_status='COMPLETED',
      completed_at=clock_timestamp(),last_error_code=null where job_id=v_job.job_id;
    return jsonb_build_object('processed',true,'outcome','COMPLETED');
  exception when query_canceled then
    update public.listing_eligibility_refresh_jobs set job_status='FAILED',
      completed_at=clock_timestamp(),last_error_code='SQLSTATE_57014' where job_id=v_job.job_id;
    return jsonb_build_object('processed',true,'outcome','FAILED');
  when others then
    get stacked diagnostics v_state=returned_sqlstate;
    update public.listing_eligibility_refresh_jobs set job_status='FAILED',
      completed_at=clock_timestamp(),last_error_code='SQLSTATE_'||v_state where job_id=v_job.job_id;
    return jsonb_build_object('processed',true,'outcome','FAILED','sqlstate',v_state);
  end;
end;

declare v_l public.listings%rowtype; v_b public.hub_batches%rowtype;
  v_id uuid; v_count integer:=0; v_ok boolean:=true; v_d public.donations%rowtype;
begin
  select * into v_l from public.listings where listing_id=p_listing for update;
  if not found then return false; end if;
  if v_l.source_type='DIRECT_DONATION' then
    select * into v_d from public.donations where donation_id=v_l.donation_id for update;
    return coalesce(found and v_d.collection_path='DIRECT_PICKUP' and v_d.donation_status=any(p_states),false);
  end if;
  if v_l.source_type<>'HUB_BATCH' then return false; end if;
  select * into v_b from public.hub_batches where batch_id=v_l.batch_id for update;
  if not found or v_b.batch_status not in ('PUBLISHED','COLLECTED') then return false; end if;
  -- Membership is immutable once published, and its parent batch is now locked.
  for v_id in select m.donation_id from public.hub_batch_members m
    where m.batch_id=v_l.batch_id and m.membership_status='ACTIVE' order by m.donation_id
  loop
    v_count:=v_count+1;
    select * into v_d from public.donations where donation_id=v_id for update;
    if not found or v_d.collection_path<>'HUB_COLLECTION'
      or not (v_d.donation_status=any(p_states)) then v_ok:=false; end if;
  end loop;
  -- Lock inventory in the same UUID order after locking the entire donation set.
  for v_id in select m.donation_id from public.hub_batch_members m
    where m.batch_id=v_l.batch_id and m.membership_status='ACTIVE' order by m.donation_id
  loop
    perform 1 from public.hub_inventory hi where hi.donation_id=v_id
      and hi.hub_id=v_b.hub_id
      and (hi.inventory_status='BATCHED'
        or ('COLLECTED'=any(p_states) and hi.inventory_status in ('COLLECTED','RECONCILIATION_REQUIRED'))) for update;
    if not found then v_ok:=false; end if;
  end loop;
  return v_ok and v_count>0 and v_count=v_b.batch_donation_count;
end;

declare v_actor uuid:=auth.uid(); v_snapshot text; v_node text;
  v_distance double precision; v_resolved_snapshot text; v_hub uuid;
begin
  if v_actor is null then raise exception 'UNAUTHENTICATED'; end if;
  if not exists(select 1 from public.hub_admin_profiles where user_id=v_actor) then
    raise exception 'HUB_ADMIN_ONLY';
  end if;
  if nullif(btrim(p_name),'') is null or nullif(btrim(p_address),'') is null then
    raise exception 'HUB_NAME_AND_ADDRESS_REQUIRED';
  end if;
  if p_capacity_kg not between 50 and 250 then raise exception 'CAPACITY_MUST_BE_50_TO_250_KG'; end if;
  if p_lat is null or p_lon is null or p_lat not between -90 and 90 or p_lon not between -180 and 180 then
    raise exception 'INVALID_HUB_COORDINATES';
  end if;
  select c.network_snapshot_id into v_snapshot from public.road_network_coverage c
   where c.active_flag and c.dataset_kind='OPERATIONAL' and c.approved_at is not null
     and c.max_snap_distance_m=500 for share;
  if v_snapshot is null then raise exception 'OPERATIONAL_ROAD_COVERAGE_UNAVAILABLE'; end if;
  select r.node_id,r.snap_distance_m,r.snapshot_id into v_node,v_distance,v_resolved_snapshot
    from public.geolock_resolve_road_node(p_lat,p_lon) r;
  if v_node is null or v_distance is null or v_distance<0 or v_distance>500
     or v_resolved_snapshot is distinct from v_snapshot then
    raise exception 'HUB_LOCATION_NOT_ROUTABLE';
  end if;
  insert into public.community_hubs(admin_user_id,hub_name,address_text,latitude,longitude,
    capacity_kg,road_node_id,active_flag)
  values(v_actor,btrim(p_name),btrim(p_address),p_lat,p_lon,p_capacity_kg,v_node,false)
  returning hub_id into v_hub;
  if not exists(select 1 from public.community_hubs h where h.hub_id=v_hub and h.road_node_id=v_node) then
    raise exception 'HUB_LOCATION_NODE_MISMATCH';
  end if;
  update public.community_hubs set active_flag=true where hub_id=v_hub and admin_user_id=v_actor;
  insert into public.audit_events(actor_user_id,actor_role,entity_type,entity_id,
    event_type,request_id,requested_state,resulting_state,reason_code,outcome,details)
  values(v_actor,'HUB_ADMIN','HUB',v_hub,'REGISTER_HUB',gen_random_uuid(),'PENDING_VALIDATION',
    'ACTIVE','SERVER_ROAD_NODE_VALIDATION','SUCCESS',
    jsonb_build_object('network_snapshot_id',v_snapshot,'road_node_id',v_node,
      'snap_distance_m',round(v_distance::numeric,1),'capacity_kg',p_capacity_kg));
  return v_hub;
end;

declare v_actor uuid:=auth.uid(); v_h public.community_hubs%rowtype;
  v_snapshot text; v_node text; v_distance double precision; v_resolved_snapshot text;
  v_commitment_change boolean;
  v_road_location_change boolean;
begin
  if v_actor is null then raise exception 'UNAUTHENTICATED'; end if;
  if nullif(btrim(p_name),'') is null or nullif(btrim(p_address),'') is null then
    raise exception 'HUB_NAME_AND_ADDRESS_REQUIRED';
  end if;
  if p_capacity_kg not between 50 and 250 then raise exception 'CAPACITY_MUST_BE_50_TO_250_KG'; end if;
  if p_lat is null or p_lon is null or p_lat not between -90 and 90 or p_lon not between -180 and 180 then
    raise exception 'INVALID_HUB_COORDINATES';
  end if;

  -- Lock coverage before the hub row to align with snapshot activation and
  -- registration. This does not lock or serialize registrations with each other.
  select c.network_snapshot_id into v_snapshot from public.road_network_coverage c
   where c.active_flag and c.dataset_kind='OPERATIONAL' and c.approved_at is not null
     and c.max_snap_distance_m=500 for share;
  select * into v_h from public.community_hubs h
   where h.hub_id=p_hub and h.admin_user_id=v_actor for update;
  if not found then raise exception 'HUB_NOT_FOUND_OR_FORBIDDEN'; end if;
  v_road_location_change := not v_h.active_flag or v_h.road_node_id is null
    or v_h.address_text is distinct from btrim(p_address)
    or v_h.latitude is distinct from p_lat or v_h.longitude is distinct from p_lon;
  v_commitment_change := v_road_location_change
    or v_h.capacity_kg is distinct from p_capacity_kg;

  if v_commitment_change and (
    exists(select 1 from public.hub_inventory i where i.hub_id=p_hub
      and i.inventory_status in ('STORED','BATCHED','RECONCILIATION_REQUIRED'))
    or exists(select 1 from public.hub_reservations r where r.hub_id=p_hub
      and r.reservation_status='ACTIVE')
    or exists(select 1 from public.hub_batch_members m where m.hub_id=p_hub
      and m.membership_status='ACTIVE')
    or exists(select 1 from public.hub_batches b where b.hub_id=p_hub
      and b.batch_status in ('DRAFT','PUBLISHED','CLAIMED'))
  ) then raise exception 'HUB_HAS_ACTIVE_INVENTORY_OR_COMMITMENTS'; end if;

  if v_road_location_change then
    if v_snapshot is null then raise exception 'OPERATIONAL_ROAD_COVERAGE_UNAVAILABLE'; end if;
    select r.node_id,r.snap_distance_m,r.snapshot_id into v_node,v_distance,v_resolved_snapshot
      from public.geolock_resolve_road_node(p_lat,p_lon) r;
    if v_node is null or v_distance is null or v_distance<0 or v_distance>500
       or v_resolved_snapshot is distinct from v_snapshot then
      raise exception 'HUB_LOCATION_NOT_ROUTABLE';
    end if;
    update public.community_hubs set hub_name=btrim(p_name),address_text=btrim(p_address),
      latitude=p_lat,longitude=p_lon,capacity_kg=p_capacity_kg,road_node_id=v_node,
      active_flag=true where hub_id=p_hub and admin_user_id=v_actor;
  elsif v_h.capacity_kg is distinct from p_capacity_kg then
    v_node:=v_h.road_node_id;
    update public.community_hubs set hub_name=btrim(p_name),capacity_kg=p_capacity_kg
      where hub_id=p_hub and admin_user_id=v_actor;
  else
    v_node:=v_h.road_node_id;
    update public.community_hubs set hub_name=btrim(p_name)
      where hub_id=p_hub and admin_user_id=v_actor;
  end if;
  if v_road_location_change and not exists(select 1 from public.community_hubs h
      where h.hub_id=p_hub and h.road_node_id=v_node and h.active_flag) then
    raise exception 'HUB_LOCATION_NODE_MISMATCH';
  end if;
  insert into public.audit_events(actor_user_id,actor_role,entity_type,entity_id,
    event_type,request_id,requested_state,resulting_state,reason_code,outcome)
  values(v_actor,'HUB_ADMIN','HUB',p_hub,'UPDATE_HUB_PROFILE',gen_random_uuid(),
    'UPDATED','UPDATED',case when v_commitment_change then 'LOCATION_AND_CAPACITY_VALIDATED' else 'PROFILE_FIELDS_UPDATED' end,
    'SUCCESS');
  return jsonb_build_object('hub_id',p_hub,'updated',true,'road_node_id',v_node);
end;

DECLARE v_actor uuid:=fleet_private.require_ngo(); v public.vehicles%rowtype;
BEGIN
  SELECT * INTO v FROM public.vehicles WHERE vehicle_id=p_vehicle_id AND ngo_user_id=v_actor FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'VEHICLE_NOT_FOUND'; END IF;
  IF p_expected_version IS NULL OR v.vehicle_version<>p_expected_version THEN RAISE EXCEPTION 'VEHICLE_VERSION_CONFLICT'; END IF;
  UPDATE public.vehicles SET active_flag=false,available_for_planning=false WHERE vehicle_id=v.vehicle_id RETURNING * INTO v;
  RETURN to_jsonb(v)-'registration_payload';
END

declare
  v_rec record; v_c public.donation_claims%rowtype; v_le public.claim_leases%rowtype;
  v_l public.listings%rowtype; v_t public.pickup_tasks%rowtype;
  v_uncertain boolean; v_count integer:=0; v_did uuid; v_cfg text; v_route_id uuid; v_binding routing_private.bindings%rowtype;
begin
  if auth.role() is distinct from 'service_role' and session_user <> 'postgres' then
    raise exception 'TRUSTED_SCHEDULER_ONLY';
  end if;
  for v_rec in
    select c.claim_id,cl.lease_id,cl.expires_at from public.donation_claims c
    join public.claim_leases cl using(claim_id)
    where c.claim_status='ACTIVE' and cl.lease_status='ACTIVE' and cl.expires_at<=clock_timestamp()
    order by cl.expires_at,c.claim_id
    limit greatest(1,least(coalesce(p_limit,100),1000))
  loop
    -- Route execution locks route scope before claim/task rows. Lock the same
    -- scope before taking the claim lock so pickup and expiry cannot race.
    v_route_id:=NULL;
    SELECT i.route_id INTO v_route_id FROM routing_private.items i
      WHERE i.task_id=(SELECT t.task_id FROM public.pickup_tasks t WHERE t.claim_id=v_rec.claim_id)
        AND i.released_at IS NULL;
    IF v_route_id IS NOT NULL THEN
      v_binding:=routing_private.lock_route_for_recovery(v_route_id);
    END IF;
    SELECT c.* INTO v_c FROM public.donation_claims c
      WHERE c.claim_id=v_rec.claim_id FOR UPDATE SKIP LOCKED;
    IF NOT FOUND THEN CONTINUE; END IF;
    select le.* into v_le from public.claim_leases le where le.lease_id=v_rec.lease_id for update;
    if v_c.claim_status<>'ACTIVE' or v_le.lease_status<>'ACTIVE'
       or v_le.expires_at>clock_timestamp() then continue; end if;
    select l.* into v_l from public.listings l where l.listing_id=v_c.listing_id for update;
    select t.* into v_t from public.pickup_tasks t where t.claim_id=v_c.claim_id for update;

    -- Unresolved custody evidence for this claim or listing fences reopening.
    v_uncertain := exists(select 1 from public.claim_reconciliation_cases rc
        where (rc.claim_id=v_c.claim_id or rc.listing_id=v_l.listing_id)
          and rc.case_status in ('OPEN','MANUAL_REVIEW'))
      or v_l.listing_id is null
      or v_t.task_id is null
      or v_l.listing_status<>'CLAIMED'
      or v_t.task_status NOT IN ('CONFIRMED','PLANNED')
      or exists(select 1 from routing_private.items i where i.task_id=v_t.task_id
        and (i.consumed_at IS NOT NULL OR i.collected_at IS NOT NULL OR i.released_at IS NOT NULL))
      or (exists(select 1 from public.active_task_route_assignments a where a.task_id=v_t.task_id)
        and not exists(select 1 from routing_private.items i where i.task_id=v_t.task_id
          and i.released_at IS NULL))
      or exists(select 1 from resolution_private.cases rc
        join routing_private.items i on i.route_id=rc.route_id
        where i.task_id=v_t.task_id and rc.status IN ('AWAITING_EVIDENCE','MANUAL_REVIEW'))
      or (v_l.source_type='DIRECT_DONATION' and exists(select 1 from public.donations d
        where d.donation_id=v_l.donation_id and d.donation_status in ('PICKUP_IN_PROGRESS','COLLECTED','DELIVERED')))
      or (v_l.source_type='HUB_BATCH' and exists(select 1 from public.hub_batch_members m
        join public.donations d using(donation_id) where m.batch_id=v_l.batch_id
        and m.membership_status='ACTIVE' and d.donation_status in ('PICKUP_IN_PROGRESS','COLLECTED','DELIVERED')));
    if v_l.source_type='DIRECT_DONATION' then
      v_uncertain:=v_uncertain or not exists(select 1 from public.donations d
        where d.donation_id=v_l.donation_id and d.donation_status='CLAIMED');
    elsif v_l.source_type='HUB_BATCH' then
      v_uncertain:=v_uncertain
        or not exists(select 1 from public.hub_batch_members m
          where m.batch_id=v_l.batch_id and m.membership_status='ACTIVE')
        or exists(select 1 from public.hub_batch_members m join public.donations d using(donation_id)
          where m.batch_id=v_l.batch_id and m.membership_status='ACTIVE'
            and d.donation_status<>'CLAIMED')
        or exists(select 1 from public.hub_batch_members m join public.hub_inventory hi using(donation_id)
          where m.batch_id=v_l.batch_id and m.membership_status='ACTIVE'
            and hi.inventory_status<>'BATCHED');
    end if;
    if v_l.listing_id is not null then
      v_uncertain:=not public.geolock_lock_listing_donations(v_l.listing_id,array['CLAIMED']) or v_uncertain;
    end if;
    -- Decide listing expiry only after acquiring the donation/batch lock set.
    -- An expired listing cannot be safely reopened; retain custody for reconciliation.
    -- A route assignment is not custody evidence. A route member is released
    -- only after an unstarted stop is safely detached from its immutable plan.
    -- Listing expiry controls whether the released listing is reopened; it does
    -- not change the authoritative pickup/custody state.
    IF NOT v_uncertain AND EXISTS(SELECT 1 FROM routing_private.items i
      WHERE i.task_id=v_t.task_id AND i.released_at IS NULL) THEN
      IF NOT routing_private.release_expired_unstarted_stop(
        v_c.claim_id,v_t.task_id,v_c.ngo_user_id,v_route_id) THEN v_uncertain:=true; END IF;
    END IF;
    IF v_uncertain THEN
      update public.claim_leases set lease_status='RECONCILIATION_REQUIRED' where lease_id=v_le.lease_id;
      update public.donation_claims set claim_status='RECONCILIATION_REQUIRED' where claim_id=v_c.claim_id;
      if v_l.listing_id is not null then
        insert into public.claim_reconciliation_cases(claim_id,listing_id,donation_id,source_type,case_status)
          values(v_c.claim_id,v_l.listing_id,v_l.donation_id,v_l.source_type,'OPEN')
          on conflict(claim_id) do nothing;
      end if;
    else
      update public.claim_leases set lease_status='RELEASED',closed_at=clock_timestamp(),release_reason='EXPIRED_SAFE_RELEASE'
        where lease_id=v_le.lease_id;
      update public.donation_claims set claim_status='RELEASED',closed_at=clock_timestamp(),close_reason='EXPIRED_SAFE_RELEASE'
        where claim_id=v_c.claim_id;
      update public.pickup_tasks set task_status='STALE' where task_id=v_t.task_id;
      IF EXISTS(SELECT 1 FROM routing_private.deferred_release_permits p
        WHERE p.task_id=v_t.task_id AND p.transaction_id=pg_current_xact_id()) THEN
        DELETE FROM public.active_task_route_assignments WHERE task_id=v_t.task_id;
        UPDATE routing_private.items SET release_xid=pg_current_xact_id(),released_at=clock_timestamp()
          WHERE task_id=v_t.task_id AND released_at IS NULL AND consumed_at IS NULL;
        UPDATE routing_private.deferred_stops SET status='RESOLVED_UNCOLLECTED',resolved_at=clock_timestamp()
          WHERE task_id=v_t.task_id AND status='DEFERRED';
      END IF;
      if v_l.listing_status='CLAIMED' THEN
        update public.listings set listing_status='AVAILABLE',listing_version=listing_version+1
          where listing_id=v_l.listing_id and listing_status='CLAIMED';
        perform public.geolock_transition_listing_donations(v_l.listing_id,'CLAIMED',
          case when v_l.source_type='DIRECT_DONATION' then 'AVAILABLE' else 'BATCHED' end,
          v_c.claim_id,NULL,'EXPIRED_SAFE_RELEASE');
      ELSE
        raise exception 'RECOVERY_LISTING_REOPEN_PRECONDITION_CHANGED';
      END IF;
    end if;
    select c.config_version into v_cfg from public.coordination_config c where c.singleton;
    insert into public.audit_events(actor_role,entity_type,entity_id,event_type,claim_id,lease_id,
      correlation_id,previous_state,requested_state,resulting_state,reason_code,outcome,
      software_version,configuration_version,details)
    values('SYSTEM','CLAIM',v_c.claim_id,'LEASE_RECOVERY',v_c.claim_id,v_le.lease_id,
      gen_random_uuid(),'ACTIVE',case when v_uncertain then 'RECONCILIATION_REQUIRED' else 'RELEASED' end,
      case when v_uncertain then 'RECONCILIATION_REQUIRED' else 'RELEASED' end,
      case when v_uncertain then 'HANDOVER_OR_AUTHORITATIVE_STATE_UNCERTAIN' else 'EXPIRED_SAFE_RELEASE' end,
      'SUCCESS','geolock-stage1-2026-10-19',v_cfg,
      jsonb_build_object('donation_id',v_l.donation_id,
        'listing_id',v_l.listing_id,'task_id',v_t.task_id));
    v_count:=v_count+1;
  end loop;
  return v_count;
end;

declare
  v_job public.ngo_eligibility_refresh_jobs%rowtype;
  v_ngo public.ngo_profiles%rowtype;
  v_active_snapshot text;
  v_sqlstate text;
begin
  if session_user <> 'postgres' then raise exception 'TRUSTED_CRON_ONLY'; end if;

  select * into v_job from public.ngo_eligibility_refresh_jobs j
   where j.job_status in ('PENDING','FAILED') and j.attempt_count<3
   order by j.requested_at desc,j.job_id desc
   limit 1 for update skip locked;
  if not found then return jsonb_build_object('processed',false); end if;

  update public.ngo_eligibility_refresh_jobs set job_status='PROCESSING',
    attempt_count=attempt_count+1,started_at=clock_timestamp(),last_error_code=null
   where job_id=v_job.job_id;

  begin
    select c.network_snapshot_id into v_active_snapshot
      from public.road_network_coverage c
     where c.active_flag and c.dataset_kind='OPERATIONAL'
       and c.approved_at is not null and c.max_snap_distance_m=500
     for share;

    select * into v_ngo from public.ngo_profiles n
     where n.user_id=v_job.ngo_user_id for update;
    if not found or not v_ngo.active_flag or v_ngo.location_verified_at is null then
      update public.ngo_eligibility_refresh_jobs set job_status='SUPERSEDED',
        completed_at=clock_timestamp(),last_error_code='NGO_LOCATION_NO_LONGER_ACTIVE'
       where job_id=v_job.job_id;
      return jsonb_build_object('processed',true,'outcome','SUPERSEDED');
    end if;

    if v_ngo.location_generation<>v_job.location_generation
       or v_ngo.road_node_id is distinct from v_job.expected_road_node_id then
      update public.ngo_eligibility_refresh_jobs set job_status='SUPERSEDED',
        completed_at=clock_timestamp(),last_error_code='LOCATION_GENERATION_CHANGED'
       where job_id=v_job.job_id;
      return jsonb_build_object('processed',true,'outcome','SUPERSEDED');
    end if;
    if v_active_snapshot is null or v_active_snapshot is distinct from v_job.expected_snapshot_id then
      update public.ngo_eligibility_refresh_jobs set job_status='FAILED',
        completed_at=clock_timestamp(),last_error_code='ROAD_SNAPSHOT_CHANGED'
       where job_id=v_job.job_id;
      return jsonb_build_object('processed',true,'outcome','FAILED','reason_code','ROAD_SNAPSHOT_CHANGED');
    end if;

    -- Existing refresh uses directed pgRouting distances and re-reads the NGO
    -- row and active snapshot while both are protected by transaction locks.
    perform public.geolock_refresh_ngo_road_eligibility(v_job.ngo_user_id);

    if exists(select 1 from public.ngo_listing_road_eligibility e
      join public.listings l on l.listing_id=e.listing_id
      where e.ngo_user_id=v_job.ngo_user_id
        and (e.network_snapshot_id<>v_job.expected_snapshot_id
          or e.ngo_road_node_id<>v_job.expected_road_node_id)
        and (l.listing_status='AVAILABLE' or exists(
          select 1 from public.donation_claims c where c.listing_id=l.listing_id
            and c.ngo_user_id=v_job.ngo_user_id
            and c.claim_status in ('ACTIVE','COMPLETED','RECONCILIATION_REQUIRED')))) then
      raise exception 'REFRESH_RESULT_SNAPSHOT_MISMATCH';
    end if;

    update public.ngo_eligibility_refresh_jobs set job_status='COMPLETED',
      completed_at=clock_timestamp(),last_error_code=null
     where job_id=v_job.job_id;
    return jsonb_build_object('processed',true,'outcome','COMPLETED',
      'location_generation',v_job.location_generation);
  exception when query_canceled then
    update public.ngo_eligibility_refresh_jobs set job_status='FAILED',
      completed_at=clock_timestamp(),last_error_code='SQLSTATE_57014'
     where job_id=v_job.job_id;
    return jsonb_build_object('processed',true,'outcome','FAILED','reason_code','SQLSTATE_57014',
      'attempt_count',v_job.attempt_count+1);
  when others then
    get stacked diagnostics v_sqlstate = returned_sqlstate;
    update public.ngo_eligibility_refresh_jobs set job_status='FAILED',
      completed_at=clock_timestamp(),last_error_code='SQLSTATE_'||v_sqlstate
     where job_id=v_job.job_id;
    return jsonb_build_object('processed',true,'outcome','FAILED','reason_code','SQLSTATE_'||v_sqlstate,
      'attempt_count',v_job.attempt_count+1);
  end;
end;

declare v_user uuid:=auth.uid(); v_generation bigint; v_status text;
begin
  if v_user is null then raise exception 'UNAUTHENTICATED'; end if;
  select location_generation into v_generation from public.ngo_profiles
   where user_id=v_user and active_flag and location_verified_at is not null;
  if not found then return 'LOCATION_REQUIRED'; end if;
  if v_generation=0 then return 'READY'; end if;
  if not exists(select 1 from public.ngo_eligibility_refresh_jobs j
    where j.ngo_user_id=v_user and j.location_generation=v_generation) then return 'FAILED'; end if;
  if exists(select 1 from public.ngo_eligibility_refresh_jobs j
    where j.ngo_user_id=v_user and j.location_generation=v_generation
      and (j.job_status in ('PENDING','PROCESSING')
        or (j.job_status='FAILED' and j.attempt_count<3))) then return 'PENDING'; end if;
  if exists(select 1 from public.ngo_eligibility_refresh_jobs j
    where j.ngo_user_id=v_user and j.location_generation=v_generation
      and (j.job_status='SUPERSEDED'
        or (j.job_status='FAILED' and j.attempt_count>=3))) then return 'FAILED'; end if;
  return 'READY';
end;

begin
  if auth.uid() is null then raise exception 'UNAUTHENTICATED'; end if;
  return query select i.image_id,i.storage_path,i.is_primary,i.content_type
    from public.hub_batch_images i
   where i.batch_id=p_batch
     and public.can_read_geolock_batch_image(i.storage_path)
   order by i.created_at,i.image_id;
end;

declare
  v_actor uuid:=auth.uid(); v_donation uuid; v_item jsonb;
  v_count integer:=0; v_weight numeric(12,3):=0; v_threshold numeric(12,3);
  v_path text; v_category uuid; v_qty integer; v_unit numeric(12,3);
  v_status text;
begin
  if v_actor is null or not exists(
    select 1 from public.donor_profiles where user_id=v_actor
  ) then raise exception 'DONOR_ONLY'; end if;
  if nullif(btrim(p_title),'') is null or nullif(btrim(p_pickup_address),'') is null
     or p_latitude is null or p_longitude is null
     or p_latitude not between -90 and 90 or p_longitude not between -180 and 180 then
    raise exception 'INVALID_DONATION_LOCATION_OR_TITLE';
  end if;
  if nullif(btrim(coalesce(p_description,'')),'') is null then
    raise exception 'DONATION_DESCRIPTION_REQUIRED';
  end if;
  if char_length(p_description)>1000 then
    raise exception 'DONATION_DESCRIPTION_TOO_LONG';
  end if;
  if jsonb_typeof(p_items) is distinct from 'array' then
    raise exception 'AT_LEAST_ONE_ITEM_REQUIRED';
  end if;
  if jsonb_array_length(p_items)=0 then raise exception 'AT_LEAST_ONE_ITEM_REQUIRED'; end if;
  select donation_direct_min_kg into v_threshold
  from public.coordination_config where singleton;
  if v_threshold is null then raise exception 'DONATION_THRESHOLD_NOT_CONFIGURED'; end if;

  -- The parent must temporarily be SUBMITTED so V3's item guard permits these
  -- inserts. This row is not externally visible until the whole RPC commits.
  insert into public.donations(
    donor_user_id,title,description,pickup_address,latitude,longitude,
    pickup_road_node_id,donation_status
  ) values(
    v_actor,p_title,p_description,p_pickup_address,p_latitude,p_longitude,
    p_pickup_road_node_id,'SUBMITTED'
  ) returning donation_id into v_donation;

  for v_item in select value from jsonb_array_elements(p_items) loop
    v_category:=(v_item->>'category_id')::uuid;
    v_qty:=(v_item->>'quantity')::integer;
    v_unit:=(v_item->>'unit_weight_kg')::numeric;
    if v_qty is null or v_qty<=0 or v_unit is null or v_unit<=0
       or nullif(btrim(v_item->>'item_name'),'') is null
       or not exists(select 1 from public.donation_categories
         where category_id=v_category and active_flag) then
      raise exception 'INVALID_DONATION_ITEM';
    end if;
    insert into public.donation_items(
      donation_id,category_id,item_name,description,quantity,unit_label,
      unit_weight_kg,item_condition
    ) values(
      v_donation,v_category,v_item->>'item_name',v_item->>'description',
      v_qty,coalesce(v_item->>'unit_label','piece'),v_unit,
      coalesce(v_item->>'item_condition','GOOD')
    );
    v_count:=v_count+1;
    v_weight:=v_weight+(v_qty*v_unit);
  end loop;
  if v_count=0 or v_weight<=0 then raise exception 'INVALID_TOTAL_WEIGHT'; end if;

  v_path:=case when v_weight>=v_threshold then 'DIRECT_PICKUP' else 'HUB_COLLECTION' end;
  v_status:=case when v_path='DIRECT_PICKUP' then 'AVAILABLE' else 'SUBMITTED' end;
  update public.donations set donation_status=v_status,
    collection_path=v_path,total_weight_kg=v_weight
  where donation_id=v_donation;

  if v_path='DIRECT_PICKUP' then
    insert into public.listings(
      source_type,donation_id,listing_weight_kg,pickup_latitude,
      pickup_longitude,pickup_road_node_id,listing_expires_at
    ) values(
      'DIRECT_DONATION',v_donation,v_weight,p_latitude,p_longitude,
      p_pickup_road_node_id,null
    );
  end if;

  insert into public.audit_events(
    actor_user_id,actor_role,entity_type,entity_id,event_type,
    previous_state,requested_state,resulting_state,outcome,details,configuration_version
  )
  select v_actor,'DONOR','DONATION',v_donation,'CREATE_DONATION',
    null,v_status,v_status,'SUCCESS',
    jsonb_build_object('validation_passed',true,'weight_kg',v_weight,
      'collection_path',v_path,'threshold_kg',v_threshold),c.config_version
  from public.coordination_config c where c.singleton;
  return v_donation;
end;

declare v_d public.donations%rowtype; v_l public.listings%rowtype;
  v_b public.hub_batches%rowtype;
begin
  select * into v_d from public.donations where donation_id=p_donation;
  if not found then return; end if;
  if v_d.collection_path is null or v_d.total_weight_kg is null or v_d.total_weight_kg<=0
    or (v_d.collection_path='DIRECT_PICKUP') is distinct from (v_d.total_weight_kg>=10)
    or (v_d.collection_path='DIRECT_PICKUP' and v_d.donation_status in ('SUBMITTED','HUB_ASSIGNED','AT_HUB','BATCHED'))
    or (v_d.collection_path='HUB_COLLECTION' and v_d.donation_status='AVAILABLE') then
    raise exception 'DONATION_FINALIZATION_REQUIRED: %',p_donation;
  end if;
  if v_d.donation_status in ('CANCELLED','SUBMITTED','HUB_ASSIGNED','AT_HUB') then return; end if;
  if v_d.collection_path='DIRECT_PICKUP' then
    select * into v_l from public.listings where donation_id=p_donation and source_type='DIRECT_DONATION';
  else
    select b.* into v_b from public.hub_batches b join public.hub_batch_members m using(batch_id)
      where m.donation_id=p_donation and m.membership_status='ACTIVE';
    if not found or v_b.batch_status<>(case when v_d.donation_status='COLLECTED' then 'COLLECTED' else 'PUBLISHED' end)
      or (select count(*) from public.hub_batch_members m
        where m.batch_id=v_b.batch_id and m.membership_status='ACTIVE')<>v_b.batch_donation_count
      or exists(select 1 from public.hub_batch_members m join public.donations d using(donation_id)
        where m.batch_id=v_b.batch_id and m.membership_status='ACTIVE'
          and (d.donation_status<>v_d.donation_status or d.collection_path<>'HUB_COLLECTION'))
      or exists(select 1 from public.hub_batch_members m where m.batch_id=v_b.batch_id
        and m.membership_status='ACTIVE' and not exists(select 1 from public.hub_inventory hi
          where hi.donation_id=m.donation_id and hi.hub_id=v_b.hub_id
            and hi.inventory_status=case when v_d.donation_status='COLLECTED' then 'COLLECTED' else 'BATCHED' end)) then
      raise exception 'BATCH_DONATION_SET_INCONSISTENT: %',p_donation;
    end if;
    select * into v_l from public.listings where batch_id=v_b.batch_id and source_type='HUB_BATCH';
  end if;
  if v_l.listing_id is null then raise exception 'DONATION_LISTING_REQUIRED: %',p_donation; end if;
  if v_d.donation_status in ('AVAILABLE','BATCHED') then
    if v_l.listing_status<>'AVAILABLE' or exists(select 1 from public.donation_claims c
      where c.listing_id=v_l.listing_id and c.claim_status in ('ACTIVE','RECONCILIATION_REQUIRED')) then
      raise exception 'AVAILABLE_DONATION_COORDINATION_MISMATCH: %',p_donation;
    end if;
  elsif v_d.donation_status='COLLECTED' then
    if v_l.listing_status<>'CLOSED' or not exists(
      select 1 from public.donation_claims c join public.claim_leases le using(claim_id)
      join public.pickup_tasks t using(claim_id)
      where c.listing_id=v_l.listing_id and t.listing_id=v_l.listing_id
        and c.claim_status='COMPLETED' and le.lease_status='COMPLETED' and t.task_status='COLLECTED') then
      raise exception 'COLLECTED_DONATION_COORDINATION_MISMATCH: %',p_donation;
    end if;
  elsif v_d.donation_status in ('CLAIMED','PICKUP_IN_PROGRESS') then
    if v_l.listing_status<>'CLAIMED' or not exists(
      select 1 from public.donation_claims c join public.claim_leases le using(claim_id)
      join public.pickup_tasks t using(claim_id)
      where c.listing_id=v_l.listing_id and t.listing_id=v_l.listing_id
        and c.claim_status in ('ACTIVE','RECONCILIATION_REQUIRED') and le.lease_status=c.claim_status
        and ((v_d.donation_status='CLAIMED' and t.task_status in ('CONFIRMED','PLANNED'))
          or (v_d.donation_status='PICKUP_IN_PROGRESS' and t.task_status='DISPATCHED'))) then
      raise exception 'CLAIMED_DONATION_COORDINATION_MISMATCH: %',p_donation;
    end if;
  end if;
end;

declare v_l public.listings%rowtype; v_id uuid; v_claim uuid; v_lease uuid; v_request uuid; v_correlation uuid:=coalesce(p_request,gen_random_uuid());
begin
  if not public.geolock_lock_listing_donations(p_listing,array[p_from]) then
    raise exception 'LISTING_DONATION_SET_STATE_MISMATCH';
  end if;
  select * into v_l from public.listings where listing_id=p_listing;
  -- Explicit context comes only from protected callers, never "latest historical claim".
  if p_claim is not null then
    select c.claim_id,le.lease_id into strict v_claim,v_lease
    from public.donation_claims c join public.claim_leases le using(claim_id)
    where c.claim_id=p_claim and c.listing_id=p_listing;
  elsif p_request is not null then
    raise exception 'AUDIT_REQUEST_WITHOUT_CLAIM_CONTEXT';
  end if;
  if p_reason is null then raise exception 'AUDIT_REASON_REQUIRED'; end if;
  v_request:=p_request; -- NULL when the caller API has no operation request ID.

  for v_id in
    select d.donation_id from public.donations d
    where (v_l.source_type='DIRECT_DONATION' and d.donation_id=v_l.donation_id)
      or (v_l.source_type='HUB_BATCH' and exists(select 1 from public.hub_batch_members m
        where m.batch_id=v_l.batch_id and m.donation_id=d.donation_id and m.membership_status='ACTIVE'))
    order by d.donation_id
  loop
    update public.donations set donation_status=p_to where donation_id=v_id and donation_status=p_from;
    if not found then raise exception 'LISTING_DONATION_SET_CHANGED'; end if;
    insert into public.audit_events(actor_user_id,actor_role,entity_type,entity_id,event_type,
      claim_id,lease_id,previous_state,requested_state,resulting_state,outcome,details,
      request_id,correlation_id,reason_code,software_version,configuration_version)
    values(auth.uid(),case when auth.uid() is null then 'SYSTEM'
      else (select role from public.user_profiles where user_id=auth.uid()) end,
      'DONATION',v_id,'DONATION_STATUS_CHANGED',v_claim,v_lease,p_from,p_to,p_to,'SUCCESS',
      jsonb_build_object('listing_id',p_listing,'donation_id',v_id,
        'ngo_id',(select ngo_user_id from public.donation_claims where claim_id=v_claim),
        'transaction_id',pg_current_xact_id()::text,'claim_context_available',p_claim is not null),v_request,v_correlation,
      p_reason,
      'geolock-claim-audit-v1',(select config_version from public.coordination_config where singleton));
  end loop;
end;

DECLARE tid uuid; rid uuid; b routing_private.bindings%rowtype; BEGIN
 SELECT t.task_id,i.route_id INTO tid,rid FROM public.pickup_tasks t LEFT JOIN routing_private.items i ON i.task_id=t.task_id AND i.released_at IS NULL WHERE t.claim_id=p_claim;
 IF rid IS NULL THEN
  PERFORM routing_private.actor_lock(auth.uid(),false);
  UPDATE routing_private.legacy_inflight SET complete_xid=pg_current_xact_id() WHERE task_id=tid;
  IF NOT FOUND THEN RAISE EXCEPTION 'NO_AUTHORIZED_OR_LEGACY_INFLIGHT_TASK'; END IF;
  PERFORM routing_private.legacy_complete_pickup(p_claim,p_handover_confirmed); RETURN;
 END IF;
 b:=routing_private.lock_route(rid,false);
 UPDATE routing_private.items SET complete_xid=pg_current_xact_id() WHERE route_id=rid AND task_id=tid AND consumed_at IS NOT NULL AND collected_at IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'PICKUP_NOT_STARTED'; END IF;
 PERFORM routing_private.legacy_complete_pickup(p_claim,p_handover_confirmed);
 UPDATE routing_private.items SET collected_at=clock_timestamp() WHERE route_id=rid AND task_id=tid;
 -- Collection is not depot return. Keep reservations until protected closure.
END

DECLARE v_actor uuid:=fleet_private.require_ngo(); v public.vehicles%rowtype; v_payload jsonb; v_node text;
BEGIN
  IF p_request_id IS NULL OR p_available IS NULL THEN RAISE EXCEPTION 'REQUEST_AND_AVAILABILITY_REQUIRED'; END IF;
  PERFORM fleet_private.check_values(p_label,p_vehicle_type,p_capacity_kg,p_fixed_cost_rm,p_distance_cost_rm_per_km,p_max_route_duration_min);
  v_payload:=jsonb_build_array(btrim(p_label),btrim(p_vehicle_type),p_capacity_kg,p_fixed_cost_rm,p_distance_cost_rm_per_km,p_max_route_duration_min,p_available);
  -- Serializes retries for this owner/request, without trusting an owner parameter.
  PERFORM pg_advisory_xact_lock(hashtextextended(v_actor::text||':'||p_request_id::text,0));
  SELECT * INTO v FROM public.vehicles WHERE ngo_user_id=v_actor AND registration_request_id=p_request_id;
  IF FOUND THEN
    IF v.registration_payload IS DISTINCT FROM v_payload THEN RAISE EXCEPTION 'REGISTRATION_REQUEST_CONFLICT'; END IF;
    RETURN to_jsonb(v)-'registration_payload';
  END IF;
  v_node:=fleet_private.require_depot(v_actor);
  INSERT INTO public.vehicles(ngo_user_id,vehicle_label,vehicle_type,payload_capacity_kg,fixed_cost_rm,
    distance_cost_rm_per_km,max_route_duration_min,depot_road_node_id,available_for_planning,registration_request_id,registration_payload)
  VALUES(v_actor,btrim(p_label),btrim(p_vehicle_type),p_capacity_kg,p_fixed_cost_rm,p_distance_cost_rm_per_km,
    p_max_route_duration_min,v_node,p_available,p_request_id,v_payload) RETURNING * INTO v;
  RETURN to_jsonb(v)-'registration_payload';
END

DECLARE v_actor uuid:=fleet_private.require_ngo(); v public.vehicles%rowtype;
BEGIN
  SELECT * INTO v FROM public.vehicles WHERE vehicle_id=p_vehicle_id AND ngo_user_id=v_actor FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'VEHICLE_NOT_FOUND'; END IF;
  IF NOT v.active_flag THEN RAISE EXCEPTION 'VEHICLE_DEACTIVATED'; END IF;
  IF p_expected_version IS NULL OR v.vehicle_version<>p_expected_version THEN RAISE EXCEPTION 'VEHICLE_VERSION_CONFLICT'; END IF;
  PERFORM fleet_private.check_values(p_label,p_vehicle_type,p_capacity_kg,p_fixed_cost_rm,p_distance_cost_rm_per_km,p_max_route_duration_min);
  UPDATE public.vehicles SET vehicle_label=btrim(p_label),vehicle_type=btrim(p_vehicle_type),payload_capacity_kg=p_capacity_kg,
    fixed_cost_rm=p_fixed_cost_rm,distance_cost_rm_per_km=p_distance_cost_rm_per_km,max_route_duration_min=p_max_route_duration_min
    WHERE vehicle_id=v.vehicle_id RETURNING * INTO v;
  RETURN to_jsonb(v)-'registration_payload';
END

DECLARE v_actor uuid:=fleet_private.require_ngo(); v public.vehicles%rowtype;
BEGIN
  SELECT * INTO v FROM public.vehicles WHERE vehicle_id=p_vehicle_id AND ngo_user_id=v_actor FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'VEHICLE_NOT_FOUND'; END IF;
  IF NOT v.active_flag THEN RAISE EXCEPTION 'VEHICLE_DEACTIVATED'; END IF;
  IF p_expected_version IS NULL OR v.vehicle_version<>p_expected_version THEN RAISE EXCEPTION 'VEHICLE_VERSION_CONFLICT'; END IF;
  IF p_available IS NULL THEN RAISE EXCEPTION 'AVAILABILITY_REQUIRED'; END IF;
  IF p_available THEN PERFORM fleet_private.require_depot(v_actor); END IF;
  UPDATE public.vehicles SET available_for_planning=p_available WHERE vehicle_id=v.vehicle_id RETURNING * INTO v;
  RETURN to_jsonb(v)-'registration_payload';
END

DECLARE g routing_private.graphs%rowtype; BEGIN
 PERFORM routing_private.worker('geolock_graph_worker');
 SELECT * INTO STRICT g FROM routing_private.graphs WHERE graph_id=p_graph;
 RETURN jsonb_build_object('graph',to_jsonb(g),
 'nodes',(SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY osm_node_id),'[]') FROM
 (SELECT osm_node_id,network_snapshot_id,active_flag FROM public.road_network_nodes WHERE p_after_node IS NULL OR osm_node_id>p_after_node ORDER BY osm_node_id LIMIT 10000) n),
 'edges',(SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY edge_id),'[]') FROM
 (SELECT edge_id,source_node,target_node,road_km,travel_minutes FROM public.road_network_edges WHERE p_after_edge IS NULL OR edge_id>p_after_edge ORDER BY edge_id LIMIT 10000) e));
END

 BEGIN
 PERFORM routing_private.worker('geolock_planner');
 RETURN (SELECT jsonb_build_object('snapshot',to_jsonb(s),'matrix',to_jsonb(m)) FROM routing_private.snapshots s
 JOIN routing_private.matrices m USING(matrix_id) WHERE snapshot_id=p_snapshot AND sealed_at IS NOT NULL);
END

 BEGIN
 PERFORM routing_private.worker('geolock_planner');
 RETURN (SELECT to_jsonb(s) FROM routing_private.snapshots s WHERE snapshot_id=p_snapshot);
END

DECLARE s routing_private.snapshots%rowtype; m routing_private.matrices%rowtype; node text; BEGIN
 PERFORM routing_private.worker('geolock_planner');
 SELECT * INTO STRICT s FROM routing_private.snapshots WHERE snapshot_id=p_snapshot FOR UPDATE;
 IF s.sealed_at IS NOT NULL THEN IF s.matrix_id IS DISTINCT FROM p_matrix THEN RAISE EXCEPTION 'SNAPSHOT_IMMUTABLE'; END IF; RETURN to_jsonb(s); END IF;
 SELECT * INTO STRICT m FROM routing_private.matrices WHERE matrix_id=p_matrix;
 IF NOT (m.body->'node_order' ? (s.body->'ngo'->>'road_node_id')) THEN RAISE EXCEPTION 'MISSING_DEPOT_NODE'; END IF;
 -- Excluded tasks need not have matrix nodes. The independent adapter and the
 -- protected publication checker require every actually admitted/served node.
 UPDATE routing_private.snapshots SET matrix_id=p_matrix,sealed_at=clock_timestamp() WHERE snapshot_id=p_snapshot RETURNING * INTO s;
 RETURN to_jsonb(s);
END

DECLARE id uuid; old jsonb; BEGIN
 PERFORM routing_private.worker('geolock_graph_worker');
 PERFORM pg_advisory_xact_lock(hashtextextended('routing-policy:'||p_request::text,0));
 SELECT policy_id,body INTO id,old FROM routing_private.policies WHERE request_id=p_request;
 IF FOUND THEN IF old IS DISTINCT FROM p_body THEN RAISE EXCEPTION 'REQUEST_CONFLICT'; END IF; RETURN id; END IF;
 IF p_request IS NULL OR p_body IS NULL OR jsonb_typeof(p_body->'mandatory') IS DISTINCT FROM 'boolean'
 OR NOT(p_body?'horizon_minutes' AND p_body?'dispatch_margin_minutes' AND p_body?'direct_service_minutes' AND p_body?'hub_service_minutes')
 OR NOT coalesce(((p_body->>'horizon_minutes')::numeric>0 AND (p_body->>'horizon_minutes')::numeric<=1440
 AND (p_body->>'dispatch_margin_minutes')::numeric>=0 AND (p_body->>'direct_service_minutes')::numeric>=0
 AND (p_body->>'hub_service_minutes')::numeric>=0 AND (p_body->>'horizon_minutes')::numeric<'Infinity'::numeric
 AND (p_body->>'dispatch_margin_minutes')::numeric<'Infinity'::numeric AND (p_body->>'direct_service_minutes')::numeric<'Infinity'::numeric
 AND (p_body->>'hub_service_minutes')::numeric<'Infinity'::numeric),false)
 OR jsonb_typeof(p_body->'solver') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_body->'execution') IS DISTINCT FROM 'object'
 THEN RAISE EXCEPTION 'EXPLICIT_ROUTING_POLICY_REQUIRED'; END IF;
 INSERT INTO routing_private.policies(request_id,body,digest) VALUES(p_request,p_body,routing_private.hash(p_body)) RETURNING policy_id INTO id;
 RETURN id;
END

DECLARE id uuid; old routing_private.graphs%rowtype; nd jsonb; ed jsonb; BEGIN
 PERFORM routing_private.worker('geolock_graph_worker');
 LOCK TABLE public.road_network_nodes,public.road_network_edges,public.road_network_coverage IN SHARE MODE;
 SELECT * INTO old FROM routing_private.graphs WHERE request_id=p_request;
 IF FOUND THEN
  IF ROW(old.coverage_snapshot,old.speed_profile,old.precision_policy) IS DISTINCT FROM ROW(p_snapshot,p_speed_profile,p_precision_policy) THEN RAISE EXCEPTION 'REQUEST_CONFLICT'; END IF;
  RETURN old.graph_id;
 END IF;
 IF p_request IS NULL OR nullif(btrim(p_speed_profile),'') IS NULL OR p_precision_policy IS DISTINCT FROM 'EXACT_MAX_6_DECIMALS'
 OR NOT EXISTS(SELECT 1 FROM public.road_network_coverage WHERE network_snapshot_id=p_snapshot AND active_flag AND dataset_kind='OPERATIONAL' AND approved_at IS NOT NULL)
 THEN RAISE EXCEPTION 'APPROVED_GRAPH_REQUIRED'; END IF;
 nd:=routing_private.network_digest('road_network_nodes','osm_node_id');
 ed:=routing_private.network_digest('road_network_edges','edge_id');
 INSERT INTO routing_private.graphs(request_id,coverage_snapshot,content_digest,speed_profile,precision_policy,node_count,edge_count)
 VALUES(p_request,p_snapshot,routing_private.hash(jsonb_build_array(nd,ed)),p_speed_profile,p_precision_policy,(nd->>'count')::bigint,(ed->>'count')::bigint) RETURNING graph_id INTO id;
 RETURN id;
END

DECLARE id uuid; old routing_private.matrices%rowtype; g routing_private.graphs%rowtype;
 n integer; i integer; j integer; node text; status text; d numeric; t numeric; BEGIN
 PERFORM routing_private.worker('geolock_graph_worker');
 PERFORM pg_advisory_xact_lock(hashtextextended('routing-matrix:'||p_request::text,0));
 SELECT * INTO old FROM routing_private.matrices WHERE request_id=p_request;
 IF FOUND THEN IF old.graph_id IS DISTINCT FROM p_graph OR old.body IS DISTINCT FROM p_body THEN RAISE EXCEPTION 'REQUEST_CONFLICT'; END IF; RETURN old.matrix_id; END IF;
 SELECT * INTO STRICT g FROM routing_private.graphs WHERE graph_id=p_graph;
 n:=jsonb_array_length(p_body->'node_order');
 IF p_request IS NULL OR n IS NULL OR n NOT BETWEEN 1 AND 100 OR p_body->>'network_snapshot_id' IS DISTINCT FROM g.coverage_snapshot
 OR p_body->>'source_kind' IS DISTINCT FROM 'OPERATIONAL_ROAD_NETWORK'
 OR p_body->>'path_policy' IS DISTINCT FROM 'DIRECTED_SHORTEST_DISTANCE_WITH_TIME_ON_SAME_PATH'
 OR p_body->>'edge_speed_profile' IS DISTINCT FROM g.speed_profile
 OR p_body->>'unavailable_policy' IS DISTINCT FROM 'FAIL_SCENARIO'
 OR (SELECT count(DISTINCT v) FROM jsonb_array_elements_text(p_body->'node_order') v)<>n
 THEN RAISE EXCEPTION 'INVALID_MATRIX_MANIFEST'; END IF;
 FOR node IN SELECT jsonb_array_elements_text(p_body->'node_order') LOOP
  IF NOT EXISTS(SELECT 1 FROM public.road_network_nodes WHERE osm_node_id=fleet_private.road_node_key(node) AND network_snapshot_id=g.coverage_snapshot AND active_flag) THEN RAISE EXCEPTION 'INVALID_MATRIX_NODE'; END IF;
 END LOOP;
 IF jsonb_array_length(p_body->'distance_km') IS DISTINCT FROM n OR jsonb_array_length(p_body->'travel_minutes') IS DISTINCT FROM n OR jsonb_array_length(p_body->'arc_status') IS DISTINCT FROM n THEN RAISE EXCEPTION 'INVALID_MATRIX_SHAPE'; END IF;
 FOR i IN 0..n-1 LOOP
 IF jsonb_array_length(p_body->'distance_km'->i) IS DISTINCT FROM n OR jsonb_array_length(p_body->'travel_minutes'->i) IS DISTINCT FROM n OR jsonb_array_length(p_body->'arc_status'->i) IS DISTINCT FROM n THEN RAISE EXCEPTION 'INVALID_MATRIX_SHAPE'; END IF;
 FOR j IN 0..n-1 LOOP
  status:=p_body->'arc_status'->i->>j;
  d:=(p_body->'distance_km'->i->>j)::numeric; t:=(p_body->'travel_minutes'->i->>j)::numeric;
  IF status IS DISTINCT FROM 'AVAILABLE' OR d IS NULL OR t IS NULL OR NOT(d>=0 AND d<'Infinity'::numeric AND t>=0 AND t<'Infinity'::numeric)
 OR d<>round(d,6) OR t<>round(t,6) OR (i=j AND (d<>0 OR t<>0)) OR (i<>j AND (d=0 OR t=0)) THEN RAISE EXCEPTION 'ROUTE_UNAVAILABLE_OR_INVALID_COST'; END IF;
 END LOOP; END LOOP;
 INSERT INTO routing_private.matrices(request_id,graph_id,body,digest) VALUES(p_request,p_graph,p_body,routing_private.hash(p_body)) RETURNING matrix_id INTO id;
 RETURN id;
END

DECLARE ngo uuid:=fleet_private.require_ngo(); c routing_private.candidates%rowtype; s routing_private.snapshots%rowtype;
 m routing_private.matrices%rowtype; v public.vehicles%rowtype; original jsonb; r jsonb; stop jsonb; obs jsonb; cur jsonb; win jsonb; a jsonb;
 ids uuid[]; served uuid[]:=ARRAY[]::uuid[]; vehicles uuid[]:=ARRAY[]::uuid[]; routes uuid[]:=ARRAY[]::uuid[];
 rid uuid; vid uuid; tid uuid; node text; last_node text; load numeric; km numeric; cursor_us numeric; arr numeric; start_us numeric; end_us numeric;
 nominal_cursor_us numeric; nominal_arr numeric; nominal_start_us numeric; nominal_end_us numeric; retimed_stops jsonb;
 request_hash text; prior routing_private.requests%rowtype; policy jsonb; ord integer; cutoff_end timestamptz; automatic_departure boolean := p_depart_at IS NULL; receipt jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.pickup_tasks'::regclass AND tgname='routing_task_authority' AND tgenabled='O')
 THEN RAISE EXCEPTION 'DISPATCH_CUTOVER_REQUIRED_BEFORE_AUTHORIZATION'; END IF;
 IF p_request IS NULL THEN RAISE EXCEPTION 'REQUEST_AND_DEPARTURE_REQUIRED'; END IF;
 PERFORM routing_private.actor_lock(ngo);
 request_hash:=CASE WHEN automatic_departure THEN routing_private.hash(jsonb_build_array('AUTHORIZE_AUTO_NOW',p_candidate)) ELSE routing_private.hash(jsonb_build_array('AUTHORIZE',p_candidate,p_depart_at)) END;
 SELECT * INTO prior FROM routing_private.requests WHERE ngo_id=ngo AND request_id=p_request;
 IF FOUND THEN IF prior.payload_digest IS DISTINCT FROM request_hash THEN RAISE EXCEPTION 'REQUEST_CONFLICT'; END IF; RETURN prior.result; END IF;
 SELECT * INTO STRICT c FROM routing_private.candidates WHERE candidate_id=p_candidate;
 SELECT * INTO STRICT s FROM routing_private.snapshots WHERE snapshot_id=c.snapshot_id;
 IF s.ngo_id<>ngo THEN RAISE EXCEPTION 'NOT_SNAPSHOT_OWNER'; END IF;
 SELECT * INTO STRICT m FROM routing_private.matrices WHERE matrix_id=s.matrix_id;
 IF NOT EXISTS(SELECT 1 FROM routing_private.validations WHERE candidate_id=c.candidate_id AND candidate_digest=c.digest)
 OR c.body->'plan'->>'method' IS DISTINCT FROM 'proposed' OR c.body->'plan'->>'feasible' IS DISTINCT FROM 'true'
 OR c.body->'plan'->>'dispatch_authority_issued' IS DISTINCT FROM 'false'
 OR NOT coalesce(jsonb_array_length(c.body->'plan'->'routes') BETWEEN 1 AND 20,false)
 THEN RAISE EXCEPTION 'VALIDATED_FEASIBLE_PLAN_REQUIRED'; END IF;
 IF routing_private.ngo_observation(ngo) IS DISTINCT FROM s.body->'ngo' THEN RAISE EXCEPTION 'PLAN_STALE_NGO'; END IF;
 policy:=s.body->'policy'; cutoff_end:=s.cutoff+make_interval(secs=>((policy->>'horizon_minutes')::numeric*60)::double precision);
 IF NOT automatic_departure AND (p_depart_at<clock_timestamp() OR p_depart_at>cutoff_end) THEN RAISE EXCEPTION 'INVALID_DEPARTURE'; END IF;
 SELECT array_agg((o->'task'->>'task_id')::uuid) INTO ids FROM jsonb_array_elements(s.body->'observations') o;
 PERFORM routing_private.lock_sources(ids);
 -- Canonical vehicle ordering prevents multi-vehicle publication deadlocks.
 PERFORM 1 FROM public.vehicles WHERE vehicle_id IN(SELECT (x->>'vehicle_id')::uuid FROM jsonb_array_elements(c.body->'plan'->'routes') x) ORDER BY vehicle_id FOR UPDATE;
 IF automatic_departure THEN
  p_depart_at:=clock_timestamp();
  IF p_depart_at>cutoff_end THEN RAISE EXCEPTION 'INVALID_DEPARTURE'; END IF;
 END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(c.body->'plan'->'routes') LOOP
  vid:=(r->>'vehicle_id')::uuid;
  IF vid=ANY(vehicles) THEN RAISE EXCEPTION 'DUPLICATE_VEHICLE'; END IF; vehicles:=array_append(vehicles,vid);
  SELECT * INTO STRICT v FROM public.vehicles WHERE vehicle_id=vid;
  SELECT x INTO original FROM jsonb_array_elements(s.body->'vehicles') x WHERE x->>'vehicle_id'=vid::text;
  IF original IS NULL OR original->>'vehicle_version' IS DISTINCT FROM v.vehicle_version::text OR v.ngo_user_id<>ngo
  OR NOT v.active_flag OR NOT v.available_for_planning OR fleet_private.vehicle_has_hold(vid)
  OR v.depot_road_node_id IS DISTINCT FROM fleet_private.require_depot(ngo) THEN RAISE EXCEPTION 'PLAN_STALE_VEHICLE'; END IF;
  IF r->>'ngo_id' IS DISTINCT FROM ngo::text OR r->>'start_node_id' IS DISTINCT FROM v.depot_road_node_id
   OR r->>'end_node_id' IS DISTINCT FROM v.depot_road_node_id OR (r->>'departure_us')::numeric IS DISTINCT FROM 0::numeric
   OR NOT coalesce(jsonb_array_length(r->'stops') BETWEEN 1 AND 100,false) THEN RAISE EXCEPTION 'INVALID_ROUTE_DEPOT_OR_STOPS'; END IF;
  rid:=gen_random_uuid(); load:=0; km:=0; cursor_us:=0; nominal_cursor_us:=0; retimed_stops:='[]'::jsonb; last_node:=v.depot_road_node_id; ord:=0;
  INSERT INTO public.pickup_routes(route_id,ngo_user_id,vehicle_id,route_status,matrix_id,authorised_at,validation_reference)
  VALUES(rid,ngo,vid,'DRAFT',m.matrix_id::text,clock_timestamp(),c.candidate_id::text);
  INSERT INTO routing_private.bindings(route_id,candidate_id,ngo_id,vehicle_id,vehicle_version,plan,departure_at)
  VALUES(rid,c.candidate_id,ngo,vid,v.vehicle_version,r,p_depart_at);
  FOR stop IN SELECT value FROM jsonb_array_elements(r->'stops') LOOP
   ord:=ord+1; tid:=(stop->>'task_id')::uuid;
   IF tid=ANY(served) THEN RAISE EXCEPTION 'DUPLICATE_TASK'; END IF; served:=array_append(served,tid);
   obs:=routing_private.snapshot_task(s.body,tid);
   IF obs IS NULL OR NOT routing_private.admissible(obs,ngo,s.cutoff,policy) THEN RAISE EXCEPTION 'UNAUTHORIZED_TASK'; END IF;
   PERFORM 1 FROM public.pickup_tasks WHERE task_id=tid FOR UPDATE;
   cur:=routing_private.observe_task(tid);
   IF routing_private.task_digest(cur) IS DISTINCT FROM routing_private.task_digest(obs)
    OR cur->'task'->>'task_status' IS DISTINCT FROM 'CONFIRMED'
    OR EXISTS(SELECT 1 FROM public.active_task_route_assignments WHERE task_id=tid) THEN RAISE EXCEPTION 'PLAN_STALE_TASK'; END IF;
   node:=obs->'task'->>'pickup_road_node_id'; win:=routing_private.task_window(obs,s.cutoff,policy);
   IF stop->>'road_node_id' IS DISTINCT FROM node THEN RAISE EXCEPTION 'UNAUTHORIZED_PICKUP_NODE'; END IF;
   a:=routing_private.arc(m.body,last_node,node);
   -- Solver offsets use a nominal zero departure at the snapshot cutoff.
   -- Validate those offsets first, then replay the same ordered route against
   -- the actual departure. Shifting nominal waits would count the delay twice.
   nominal_arr:=nominal_cursor_us+(a->>'minutes')::numeric*60000000;
   nominal_start_us:=greatest(nominal_arr,extract(epoch FROM ((win->>'start')::timestamptz-s.cutoff))*1000000);
   nominal_end_us:=nominal_start_us+(win->>'service')::numeric*60000000;
   arr:=cursor_us+(a->>'minutes')::numeric*60000000;
   start_us:=greatest(arr,extract(epoch FROM ((win->>'start')::timestamptz-p_depart_at))*1000000);
   end_us:=start_us+(win->>'service')::numeric*60000000;
   IF (stop->>'arrival_us')::numeric IS DISTINCT FROM nominal_arr OR (stop->>'service_start_us')::numeric IS DISTINCT FROM nominal_start_us
    OR (stop->>'departure_us')::numeric IS DISTINCT FROM nominal_end_us
    OR s.cutoff+make_interval(secs=>(nominal_end_us/1000000)::double precision)>(win->>'end')::timestamptz
    OR p_depart_at+make_interval(secs=>(end_us/1000000)::double precision)>(win->>'end')::timestamptz THEN RAISE EXCEPTION 'ROUTE_SCHEDULE_INVALID'; END IF;
   retimed_stops:=retimed_stops||jsonb_build_array(stop||jsonb_build_object('arrival_us',arr,'service_start_us',start_us,'departure_us',end_us));
   load:=load+(obs->'task'->>'load_kg')::numeric; km:=km+(a->>'km')::numeric;
   IF load>v.payload_capacity_kg OR (stop->>'cumulative_load_kg')::numeric IS DISTINCT FROM load THEN RAISE EXCEPTION 'CAPACITY_VIOLATION'; END IF;
   INSERT INTO routing_private.items(route_id,task_id,ordinal,observation_digest,planned_xid) VALUES(rid,tid,ord,routing_private.task_digest(obs),pg_current_xact_id());
   INSERT INTO public.active_task_route_assignments(task_id,route_id) VALUES(tid,rid);
   INSERT INTO public.pickup_route_stops(route_id,ngo_user_id,stop_order,task_id,planned_arrival)
    VALUES(rid,ngo,ord,tid,p_depart_at+make_interval(secs=>(arr/1000000)::double precision));
   UPDATE public.pickup_tasks SET task_status='PLANNED' WHERE task_id=tid;
   cursor_us:=end_us; nominal_cursor_us:=nominal_end_us; last_node:=node;
  END LOOP;
  a:=routing_private.arc(m.body,last_node,v.depot_road_node_id); cursor_us:=cursor_us+(a->>'minutes')::numeric*60000000; km:=km+(a->>'km')::numeric;
  nominal_cursor_us:=nominal_cursor_us+(a->>'minutes')::numeric*60000000;
  IF (r->>'return_us')::numeric IS DISTINCT FROM nominal_cursor_us OR nominal_cursor_us>v.max_route_duration_min*60000000 OR cursor_us>v.max_route_duration_min*60000000
   OR p_depart_at+make_interval(secs=>(cursor_us/1000000)::double precision)>cutoff_end THEN RAISE EXCEPTION 'ROUTE_DURATION_INVALID'; END IF;
  IF EXISTS(SELECT 1 FROM routing_private.items i WHERE route_id=rid AND
    (routing_private.snapshot_task(s.body,i.task_id)->'lease'->>'expires_at')::timestamptz<=p_depart_at+make_interval(secs=>(cursor_us/1000000+(policy->>'dispatch_margin_minutes')::numeric*60)::double precision)) THEN RAISE EXCEPTION 'LEASE_TOO_SHORT'; END IF;
  UPDATE public.pickup_routes SET route_status='AUTHORISED',total_distance_km=km,total_duration_min=cursor_us/60000000 WHERE route_id=rid;
  UPDATE routing_private.bindings SET plan=r||jsonb_build_object('stops',retimed_stops,'return_us',cursor_us) WHERE route_id=rid;
  routes:=array_append(routes,rid);
 END LOOP;
 IF (policy->>'mandatory')::boolean AND EXISTS(SELECT 1 FROM jsonb_array_elements(s.body->'observations') o WHERE routing_private.admissible(o,ngo,s.cutoff,policy) AND NOT((o->'task'->>'task_id')::uuid=ANY(served))) THEN RAISE EXCEPTION 'MANDATORY_TASK_UNSERVED'; END IF;
 -- Claimed unserved IDs must equal the exact admitted-task complement.
 IF (SELECT coalesce(array_agg(x ORDER BY x),ARRAY[]::text[]) FROM jsonb_array_elements_text(c.body->'plan'->'unserved_tasks') x)
 IS DISTINCT FROM (SELECT coalesce(array_agg(o->'task'->>'task_id' ORDER BY o->'task'->>'task_id'),ARRAY[]::text[]) FROM jsonb_array_elements(s.body->'observations') o
 WHERE routing_private.admissible(o,ngo,s.cutoff,policy) AND NOT((o->'task'->>'task_id')::uuid=ANY(served))) THEN RAISE EXCEPTION 'UNSERVED_TASK_MISMATCH'; END IF;
 receipt:=jsonb_build_object('route_ids',routes,'candidate_id',p_candidate);
 IF automatic_departure THEN receipt:=receipt||jsonb_build_object('snapshot_id',s.snapshot_id,'departure_mode','AUTO_NOW','planned_departure_at',p_depart_at); END IF;
 INSERT INTO routing_private.requests VALUES(ngo,p_request,'AUTHORIZE',request_hash,receipt);
 INSERT INTO public.audit_events(actor_user_id,actor_role,entity_type,entity_id,event_type,outcome,details)
 VALUES(ngo,'NGO','ROUTING',p_candidate,'AUTHORIZE_ROUTING','SUCCESS',jsonb_build_object('routes',routes,'candidate_digest',c.digest));
 RETURN receipt;
END

DECLARE ngo uuid:=fleet_private.require_ngo(); old routing_private.snapshots%rowtype; raw jsonb; pol jsonb; cut timestamptz:=statement_timestamp(); id uuid;
BEGIN
 PERFORM fleet_private.require_depot(ngo);
 IF p_vehicle_ids IS NOT NULL THEN
  IF cardinality(p_vehicle_ids)>20 OR cardinality(p_vehicle_ids)<>(SELECT count(DISTINCT x) FROM unnest(p_vehicle_ids) x)
  OR EXISTS(SELECT 1 FROM unnest(p_vehicle_ids) x WHERE x IS NULL OR NOT EXISTS(SELECT 1 FROM public.vehicles v WHERE v.vehicle_id=x AND v.ngo_user_id=ngo))
  THEN RAISE EXCEPTION 'INVALID_OWNED_VEHICLE_SELECTION'; END IF;
  SELECT array_agg(x ORDER BY x) INTO p_vehicle_ids FROM unnest(p_vehicle_ids) x;
  p_vehicle_ids:=coalesce(p_vehicle_ids,ARRAY[]::uuid[]);
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('routing-ngo:'||ngo::text,0));
 SELECT * INTO old FROM routing_private.snapshots WHERE ngo_id=ngo AND request_id=p_request;
 IF FOUND THEN IF old.policy_id IS DISTINCT FROM p_policy OR old.body->'selected_vehicle_ids' IS DISTINCT FROM coalesce(to_jsonb(p_vehicle_ids),'null'::jsonb) THEN RAISE EXCEPTION 'REQUEST_CONFLICT'; END IF; RETURN to_jsonb(old); END IF;
 SELECT body INTO STRICT pol FROM routing_private.policies WHERE policy_id=p_policy;
 IF p_request IS NULL THEN RAISE EXCEPTION 'REQUEST_REQUIRED'; END IF;
 SELECT jsonb_build_object('ngo',routing_private.ngo_observation(ngo),'policy',pol,'selected_vehicle_ids',p_vehicle_ids,
 'observations',coalesce((SELECT jsonb_agg(routing_private.observe_task(task_id) ORDER BY task_id) FROM public.pickup_tasks WHERE ngo_user_id=ngo AND task_status='CONFIRMED'),'[]'),
 'vehicles',coalesce((SELECT jsonb_agg(to_jsonb(v)-'registration_payload' ORDER BY vehicle_id) FROM public.vehicles v WHERE ngo_user_id=ngo AND (p_vehicle_ids IS NULL OR vehicle_id=ANY(p_vehicle_ids)) AND active_flag AND available_for_planning AND NOT fleet_private.vehicle_has_hold(vehicle_id)),'[]')) INTO raw;
 IF jsonb_array_length(raw->'observations')>100 THEN RAISE EXCEPTION 'PLANNING_SCOPE_TOO_LARGE'; END IF;
 INSERT INTO routing_private.snapshots(ngo_id,request_id,policy_id,cutoff,body,digest) VALUES(ngo,p_request,p_policy,cut,raw,routing_private.hash(raw)) RETURNING snapshot_id INTO id;
 RETURN (SELECT to_jsonb(s) FROM routing_private.snapshots s WHERE snapshot_id=id);
END

DECLARE c routing_private.candidates%rowtype; BEGIN
 PERFORM routing_private.worker('geolock_planner');
 PERFORM pg_advisory_xact_lock(hashtextextended('routing-candidate:'||p_request::text,0));
 SELECT * INTO c FROM routing_private.candidates WHERE request_id=p_request;
 IF FOUND THEN IF c.snapshot_id IS DISTINCT FROM p_snapshot OR c.body IS DISTINCT FROM p_body THEN RAISE EXCEPTION 'REQUEST_CONFLICT'; END IF; RETURN to_jsonb(c); END IF;
 IF p_request IS NULL OR NOT EXISTS(SELECT 1 FROM routing_private.snapshots WHERE snapshot_id=p_snapshot AND sealed_at IS NOT NULL) THEN RAISE EXCEPTION 'SEALED_SNAPSHOT_REQUIRED'; END IF;
 INSERT INTO routing_private.candidates(request_id,snapshot_id,body,digest) VALUES(p_request,p_snapshot,p_body,routing_private.hash(p_body)) RETURNING * INTO c;
 RETURN to_jsonb(c);
END

 BEGIN
 PERFORM routing_private.worker('geolock_validator');
 RETURN (SELECT jsonb_build_object('candidate',to_jsonb(c),'snapshot',to_jsonb(s),'matrix',to_jsonb(m))
 FROM routing_private.candidates c JOIN routing_private.snapshots s USING(snapshot_id) JOIN routing_private.matrices m USING(matrix_id) WHERE c.candidate_id=p_candidate);
END

DECLARE c routing_private.candidates%rowtype; old routing_private.validations%rowtype; s routing_private.snapshots%rowtype; m routing_private.matrices%rowtype; BEGIN
 PERFORM routing_private.worker('geolock_validator');
 SELECT * INTO STRICT c FROM routing_private.candidates WHERE candidate_id=p_candidate;
 SELECT * INTO STRICT s FROM routing_private.snapshots WHERE snapshot_id=c.snapshot_id;
 SELECT * INTO STRICT m FROM routing_private.matrices WHERE matrix_id=s.matrix_id;
 IF c.digest IS DISTINCT FROM p_digest OR p_report->>'candidate_digest' IS DISTINCT FROM c.digest
 OR p_report->>'snapshot_digest' IS DISTINCT FROM s.digest OR p_report->>'matrix_digest' IS DISTINCT FROM m.digest
 OR p_report->>'input_sha256' IS DISTINCT FROM c.body->'plan'->>'snapshot_sha256'
 OR p_report->>'matrix_sha256' IS DISTINCT FROM c.body->'plan'->>'matrix_sha256'
 OR p_report->>'valid' IS DISTINCT FROM 'true' OR p_report->>'feasible' IS DISTINCT FROM 'true'
 OR nullif(p_report->>'validator_build','') IS NULL THEN RAISE EXCEPTION 'TRUSTED_VALIDATION_REQUIRED'; END IF;
 SELECT * INTO old FROM routing_private.validations WHERE candidate_id=p_candidate;
 IF FOUND THEN IF old.report IS DISTINCT FROM p_report THEN RAISE EXCEPTION 'VALIDATION_CONFLICT'; END IF; RETURN; END IF;
 INSERT INTO routing_private.validations VALUES(p_candidate,p_digest,p_report,current_setting('role'),clock_timestamp());
END

DECLARE b routing_private.bindings%rowtype; BEGIN
 b:=routing_private.lock_route(p_route,false);
 IF p_depot_return_confirmed IS DISTINCT FROM true THEN RAISE EXCEPTION 'DEPOT_RETURN_CONFIRMATION_REQUIRED'; END IF;
 IF b.closed_at IS NOT NULL THEN
  IF (SELECT route_status FROM public.pickup_routes WHERE route_id=p_route)<>'COMPLETED' THEN RAISE EXCEPTION 'ROUTE_NOT_COMPLETED'; END IF;
  RETURN;
 END IF;
 PERFORM routing_private.close_collected(p_route);
END

DECLARE tid uuid; rid uuid; b routing_private.bindings%rowtype; BEGIN
 SELECT t.task_id,i.route_id INTO tid,rid FROM public.pickup_tasks t JOIN routing_private.items i USING(task_id)
 WHERE t.claim_id=p_claim AND i.released_at IS NULL;
 IF rid IS NULL THEN RAISE EXCEPTION 'DATABASE_DISPATCH_AUTHORIZATION_REQUIRED'; END IF;
 b:=routing_private.lock_route(rid);
 PERFORM routing_private.check_remaining(rid,tid,clock_timestamp());
 UPDATE routing_private.items SET dispatch_xid=pg_current_xact_id(),consumed_at=clock_timestamp() WHERE route_id=rid AND task_id=tid AND consumed_at IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'DISPATCH_ALREADY_CONSUMED'; END IF;
 UPDATE routing_private.bindings SET started_at=coalesce(started_at,clock_timestamp()) WHERE route_id=rid;
 UPDATE public.pickup_routes SET route_status='IN_PROGRESS' WHERE route_id=rid;
 PERFORM routing_private.legacy_start_pickup(p_claim);
END

DECLARE b routing_private.bindings%rowtype; i record; BEGIN
 b:=routing_private.lock_route(p_route,false);
 IF b.closed_at IS NOT NULL THEN
  IF (SELECT route_status FROM public.pickup_routes WHERE route_id=p_route)<>'CANCELLED' THEN RAISE EXCEPTION 'ROUTE_NOT_CANCELLED'; END IF;
  RETURN;
 END IF;
 IF b.started_at IS NOT NULL OR EXISTS(SELECT 1 FROM routing_private.items WHERE route_id=p_route AND consumed_at IS NOT NULL)
 THEN RAISE EXCEPTION 'STARTED_ROUTE_REQUIRES_RECONCILIATION'; END IF;
 FOR i IN SELECT x.*,t.task_status FROM routing_private.items x JOIN public.pickup_tasks t USING(task_id) WHERE x.route_id=p_route LOOP
  IF i.task_status<>'PLANNED' OR routing_private.task_digest(routing_private.observe_task(i.task_id)) IS DISTINCT FROM i.observation_digest
  THEN RAISE EXCEPTION 'STALE_ROUTE_REQUIRES_RECONCILIATION'; END IF;
 END LOOP;
 -- Preserve evidence outside the active planning relation. Existing recovery
 -- treats ANY public stop as execution uncertainty, even a cancelled plan.
 INSERT INTO routing_private.cancelled_stop_history(route_id,task_id,ngo_id,stop_order,original_stop)
 SELECT route_id,task_id,ngo_user_id,stop_order,to_jsonb(s) FROM public.pickup_route_stops s WHERE route_id=p_route;
 DELETE FROM public.pickup_route_stops WHERE route_id=p_route;
 DELETE FROM public.active_task_route_assignments WHERE route_id=p_route;
 UPDATE routing_private.items SET release_xid=pg_current_xact_id(),released_at=clock_timestamp() WHERE route_id=p_route;
 UPDATE public.pickup_tasks SET task_status='CONFIRMED' WHERE task_id IN(SELECT task_id FROM routing_private.items WHERE route_id=p_route);
 UPDATE public.pickup_routes SET route_status='CANCELLED' WHERE route_id=p_route;
 UPDATE routing_private.bindings SET closed_at=clock_timestamp() WHERE route_id=p_route;
 INSERT INTO public.audit_events(actor_user_id,actor_role,entity_type,entity_id,event_type,outcome,details)
 VALUES(auth.uid(),'NGO','ROUTE',p_route,'CANCEL_UNSTARTED_ROUTE','SUCCESS',jsonb_build_object('stops_archived',true,'tasks_retained',true));
END

 BEGIN
 IF TG_OP<>'UPDATE' THEN RAISE EXCEPTION 'SNAPSHOT_IMMUTABLE'; END IF;
 IF OLD.sealed_at IS NOT NULL OR NEW.matrix_id IS NULL OR NEW.sealed_at IS NULL
 OR (to_jsonb(NEW)-'matrix_id'-'sealed_at') IS DISTINCT FROM (to_jsonb(OLD)-'matrix_id'-'sealed_at')
 THEN RAISE EXCEPTION 'SNAPSHOT_IMMUTABLE'; END IF;
 RETURN NEW;
END

DECLARE after_key bigint; last_key bigint; page_hash text; n bigint; total bigint:=0; chain text:=routing_private.hash('[]'::jsonb); BEGIN
 IF (p_table,p_key) NOT IN (('road_network_nodes','osm_node_id'),('road_network_edges','edge_id')) THEN RAISE EXCEPTION 'INVALID_GRAPH_RELATION'; END IF;
 LOOP
  EXECUTE format('SELECT routing_private.hash(coalesce(jsonb_agg(to_jsonb(t) ORDER BY %I),''[]'')),max(%I),count(*) FROM
   (SELECT * FROM public.%I WHERE $1 IS NULL OR %I>$1 ORDER BY %I LIMIT 10000) t',p_key,p_key,p_table,p_key,p_key)
   INTO page_hash,last_key,n USING after_key;
  EXIT WHEN n=0;
  chain:=routing_private.hash(jsonb_build_array(chain,page_hash,last_key,n)); total:=total+n; after_key:=last_key;
 END LOOP;
 RETURN jsonb_build_object('digest',chain,'count',total,'page_size',10000);
END

DECLARE i integer; j integer; BEGIN
 SELECT ordinality::integer-1 INTO i FROM jsonb_array_elements_text(p_matrix->'node_order') WITH ORDINALITY WHERE value=p_from;
 SELECT ordinality::integer-1 INTO j FROM jsonb_array_elements_text(p_matrix->'node_order') WITH ORDINALITY WHERE value=p_to;
 IF i IS NULL OR j IS NULL OR p_matrix->'arc_status'->i->>j IS DISTINCT FROM 'AVAILABLE' THEN RAISE EXCEPTION 'ROUTE_UNAVAILABLE'; END IF;
 RETURN jsonb_build_object('km',p_matrix->'distance_km'->i->j,'minutes',p_matrix->'travel_minutes'->i->j);
END

 BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'READ_COMMITTED_REQUIRED'; END IF;
 IF auth.uid() IS DISTINCT FROM p_ngo THEN RAISE EXCEPTION 'NOT_ROUTE_OWNER'; END IF;
 PERFORM 1 FROM public.ngo_profiles WHERE user_id=p_ngo AND (NOT p_active OR active_flag) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ACTIVE_NGO_REQUIRED'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('routing-ngo:'||p_ngo::text,0));
END

 DECLARE lid uuid; BEGIN
 PERFORM 1 FROM public.donation_claims c JOIN public.pickup_tasks t USING(claim_id)
 WHERE t.task_id=ANY(p_tasks) ORDER BY c.claim_id FOR UPDATE OF c;
 PERFORM 1 FROM public.claim_leases le JOIN public.pickup_tasks t USING(claim_id)
 WHERE t.task_id=ANY(p_tasks) ORDER BY le.lease_id FOR UPDATE OF le;
 PERFORM 1 FROM public.listings l JOIN public.pickup_tasks t USING(listing_id)
 WHERE t.task_id=ANY(p_tasks) ORDER BY l.listing_id FOR UPDATE OF l;
 FOR lid IN SELECT DISTINCT listing_id FROM public.pickup_tasks WHERE task_id=ANY(p_tasks) ORDER BY listing_id LOOP
  PERFORM public.geolock_lock_listing_donations(lid,ARRAY['CLAIMED','PICKUP_IN_PROGRESS','COLLECTED']);
 END LOOP;
 PERFORM 1 FROM public.community_hubs h WHERE h.hub_id IN(SELECT b.hub_id FROM public.hub_batches b JOIN public.listings l USING(batch_id)
 JOIN public.pickup_tasks t USING(listing_id) WHERE t.task_id=ANY(p_tasks)) ORDER BY h.hub_id FOR SHARE;
END

 BEGIN
 -- Native operators never inherit an authenticated participant's JWT context.
 -- Inspect raw settings first: even malformed JSON/UUIDs must fail before replay.
 IF coalesce(current_setting('request.jwt.claim.sub',true),'')<>''
 OR coalesce(current_setting('request.jwt.claims',true),'')<>''
 OR coalesce(current_setting('request.jwt.claim.role',true),'')<>'' THEN RAISE EXCEPTION 'RESOLVER_JWT_CONTEXT_FORBIDDEN'; END IF;
 IF NOT pg_has_role(session_user,'geolock_route_resolver','MEMBER') OR NOT EXISTS(SELECT 1 FROM resolution_private.operators WHERE login_name=session_user AND active) THEN RAISE EXCEPTION 'RESTRICTED_RESOLVER_REQUIRED'; END IF;
 RETURN 'resolver:'||session_user;
END

DECLARE b routing_private.bindings%rowtype; ids uuid[]; BEGIN
 SELECT * INTO STRICT b FROM routing_private.bindings WHERE route_id=p_route;
 PERFORM routing_private.actor_lock(b.ngo_id,p_active);
 SELECT array_agg(task_id ORDER BY task_id) INTO ids FROM routing_private.items WHERE route_id=p_route;
 PERFORM routing_private.lock_sources(ids);
 PERFORM 1 FROM public.vehicles WHERE vehicle_id=b.vehicle_id FOR UPDATE;
 PERFORM 1 FROM public.pickup_routes WHERE route_id=p_route FOR UPDATE;
 PERFORM 1 FROM public.pickup_tasks WHERE task_id=ANY(ids) ORDER BY task_id FOR UPDATE;
 SELECT * INTO STRICT b FROM routing_private.bindings WHERE route_id=p_route FOR UPDATE;
 RETURN b;
END

 BEGIN
 IF NOT EXISTS(SELECT 1 FROM routing_private.items WHERE route_id=p_route)
 OR EXISTS(SELECT 1 FROM routing_private.items i JOIN public.pickup_tasks t USING(task_id)
 JOIN public.donation_claims c USING(claim_id) JOIN public.claim_leases le USING(claim_id)
 WHERE i.route_id=p_route AND (t.task_status<>'COLLECTED' OR c.claim_status<>'COMPLETED' OR le.lease_status<>'COMPLETED'))
 THEN RAISE EXCEPTION 'ROUTE_HAS_UNRESOLVED_TASKS'; END IF;
 DELETE FROM public.active_task_route_assignments WHERE route_id=p_route;
 UPDATE public.pickup_routes SET route_status='COMPLETED' WHERE route_id=p_route;
 UPDATE routing_private.items SET released_at=coalesce(released_at,clock_timestamp()) WHERE route_id=p_route;
 UPDATE routing_private.bindings SET closed_at=coalesce(closed_at,clock_timestamp()) WHERE route_id=p_route;
 INSERT INTO public.audit_events(actor_user_id,actor_role,entity_type,entity_id,event_type,outcome,details)
 VALUES(auth.uid(),'NGO','ROUTE',p_route,'CLOSE_COLLECTED_ROUTE','SUCCESS',jsonb_build_object('assignments_cleared',true));
END

declare v_actor uuid:=auth.uid();v_c public.donation_claims%rowtype;
 v_l public.listings%rowtype;v_lease public.claim_leases%rowtype;
begin
 select * into v_c from public.donation_claims where claim_id=p_claim for update;
 if not found or v_c.ngo_user_id is distinct from v_actor or v_c.claim_status<>'ACTIVE'
 then raise exception 'NOT_ACTIVE_CLAIM_HOLDER'; end if;
 select * into v_lease from public.claim_leases where claim_id=p_claim for update;
 if not found or v_lease.lease_status<>'ACTIVE' or v_lease.expires_at<=clock_timestamp()
 then raise exception 'STALE_OR_EXPIRED_LEASE'; end if;
 select * into v_l from public.listings where listing_id=v_c.listing_id for update;
 if v_l.listing_status<>'CLAIMED' then raise exception 'LISTING_NOT_CLAIMED'; end if;
 update public.pickup_tasks set task_status='DISPATCHED'
 where claim_id=p_claim and task_status in ('CONFIRMED','PLANNED');
 if not found then raise exception 'PICKUP_TASK_NOT_DISPATCHABLE'; end if;
 perform public.geolock_transition_listing_donations(v_l.listing_id,'CLAIMED','PICKUP_IN_PROGRESS',p_claim,NULL,'PICKUP_STARTED');
 insert into public.audit_events(actor_user_id,actor_role,entity_type,entity_id,event_type,
 claim_id,lease_id,requested_state,resulting_state,outcome)
 values(v_actor,'NGO','CLAIM',p_claim,'START_PICKUP',p_claim,v_lease.lease_id,
 'PICKUP_IN_PROGRESS','PICKUP_IN_PROGRESS','SUCCESS');
end

declare v_actor uuid:=auth.uid();v_c public.donation_claims%rowtype;
 v_l public.listings%rowtype;v_lease public.claim_leases%rowtype;
begin
 select * into v_c from public.donation_claims where claim_id=p_claim for update;
 if not found or v_c.ngo_user_id is distinct from v_actor or v_c.claim_status<>'ACTIVE'
 then raise exception 'NOT_ACTIVE_CLAIM_HOLDER'; end if;
 select * into v_lease from public.claim_leases where claim_id=p_claim for update;
 if not found or v_lease.lease_status<>'ACTIVE' or v_lease.expires_at<=clock_timestamp()
 then raise exception 'STALE_OR_EXPIRED_LEASE'; end if;
 if p_handover_confirmed is distinct from true then raise exception 'HANDOVER_NOT_CONFIRMED'; end if;
 select * into v_l from public.listings where listing_id=v_c.listing_id for update;
 if v_l.listing_status<>'CLAIMED' then raise exception 'LISTING_NOT_CLAIMED'; end if;
 update public.pickup_tasks set task_status='COLLECTED'
 where claim_id=p_claim and task_status='DISPATCHED';
 if not found then raise exception 'PICKUP_NOT_STARTED'; end if;
 perform public.geolock_transition_listing_donations(v_l.listing_id,'PICKUP_IN_PROGRESS','COLLECTED',p_claim,NULL,'PICKUP_COLLECTED');
 if v_l.source_type='HUB_BATCH' then
  update public.hub_inventory set inventory_status='COLLECTED'
  where donation_id in(select donation_id from public.hub_batch_members
    where batch_id=v_l.batch_id and membership_status='ACTIVE');
  update public.hub_batches set batch_status='COLLECTED' where batch_id=v_l.batch_id;
 end if;
 update public.listings set listing_status='CLOSED',listing_version=listing_version+1
 where listing_id=v_l.listing_id;
 update public.donation_claims set claim_status='COMPLETED',closed_at=clock_timestamp()
 where claim_id=p_claim;
 update public.claim_leases set lease_status='COMPLETED',closed_at=clock_timestamp()
 where claim_id=p_claim;
 insert into public.audit_events(actor_user_id,actor_role,entity_type,entity_id,event_type,
 claim_id,lease_id,requested_state,resulting_state,outcome)
 values(v_actor,'NGO','CLAIM',p_claim,'COMPLETE_PICKUP',p_claim,v_lease.lease_id,
 'COLLECTED','COLLECTED','SUCCESS');
end

DECLARE ngo uuid; rid uuid; ids uuid[]; owner_after uuid;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'UNAUTHENTICATED'; END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'READ_COMMITTED_REQUIRED'; END IF;
 SELECT ngo_user_id INTO ngo FROM public.donation_claims WHERE claim_id=p_claim;
 IF NOT FOUND THEN RAISE EXCEPTION 'CLAIM_NOT_FOUND'; END IF;
 IF NOT routing_private.reconciliation_participant(p_claim) THEN RAISE EXCEPTION 'RECONCILIATION_PARTICIPANT_ONLY'; END IF;
 -- Same prefix as actor_lock, but donor/hub participants are allowed ONLY
 -- through the unchanged reconciliation authorization and evidence checks.
 PERFORM 1 FROM public.ngo_profiles WHERE user_id=ngo FOR SHARE;
 PERFORM pg_advisory_xact_lock(hashtextextended('routing-ngo:'||ngo::text,0));
 SELECT ngo_user_id INTO owner_after FROM public.donation_claims WHERE claim_id=p_claim;
 IF owner_after IS DISTINCT FROM ngo THEN RAISE EXCEPTION 'RECONCILIATION_OWNER_CHANGED'; END IF;
 SELECT i.route_id INTO rid FROM routing_private.items i
 JOIN public.pickup_tasks t USING(task_id) WHERE t.claim_id=p_claim AND i.released_at IS NULL;
 IF rid IS NULL THEN
  PERFORM 1 FROM public.donation_claims WHERE claim_id=p_claim FOR UPDATE;
  RETURN;
 END IF;
 -- Exactly the managed route lock order: all claims, leases, listings,
 -- donations/inventory/hubs, then vehicle, route, tasks and binding.
 SELECT array_agg(task_id ORDER BY task_id) INTO ids FROM routing_private.items WHERE route_id=rid;
 PERFORM routing_private.lock_sources(ids);
 PERFORM 1 FROM public.vehicles WHERE vehicle_id=(SELECT vehicle_id FROM routing_private.bindings WHERE route_id=rid) FOR UPDATE;
 PERFORM 1 FROM public.pickup_routes WHERE route_id=rid FOR UPDATE;
 PERFORM 1 FROM public.pickup_tasks WHERE task_id=ANY(ids) ORDER BY task_id FOR UPDATE;
 PERFORM 1 FROM routing_private.bindings WHERE route_id=rid AND ngo_id=ngo FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'RECONCILIATION_ROUTE_BINDING_MISSING'; END IF;
END

DECLARE t public.pickup_tasks%rowtype; c public.donation_claims%rowtype;
 le public.claim_leases%rowtype; rc public.claim_reconciliation_cases%rowtype;
 counterpart uuid; lid uuid; rid uuid; expected_role text;
BEGIN
 IF NOT routing_private.reconciliation_participant(p_claim) THEN RAISE EXCEPTION 'RECONCILIATION_PARTICIPANT_ONLY'; END IF;
 SELECT * INTO STRICT c FROM public.donation_claims WHERE claim_id=p_claim;
 SELECT * INTO STRICT le FROM public.claim_leases WHERE claim_id=p_claim;
 SELECT * INTO STRICT t FROM public.pickup_tasks WHERE claim_id=p_claim;
 SELECT * INTO STRICT rc FROM public.claim_reconciliation_cases
  WHERE claim_id=p_claim AND case_status IN ('OPEN','MANUAL_REVIEW');
 IF c.claim_status<>'RECONCILIATION_REQUIRED' OR le.lease_status<>'RECONCILIATION_REQUIRED'
 OR t.task_status NOT IN ('DISPATCHED','COLLECTED') OR rc.listing_id IS DISTINCT FROM c.listing_id
 THEN RAISE EXCEPTION 'RECONCILIATION_COLLECTION_STATE_MISMATCH'; END IF;
 SELECT CASE WHEN l.source_type='DIRECT_DONATION' THEN d.donor_user_id ELSE h.admin_user_id END,
        CASE WHEN l.source_type='DIRECT_DONATION' THEN 'DONOR' ELSE 'HUB_ADMIN' END,l.listing_id
 INTO counterpart,expected_role,lid FROM public.listings l
 LEFT JOIN public.donations d ON d.donation_id=l.donation_id
 LEFT JOIN public.hub_batches b ON b.batch_id=l.batch_id
 LEFT JOIN public.community_hubs h ON h.hub_id=b.hub_id WHERE l.listing_id=c.listing_id;
 IF counterpart IS NULL OR counterpart=c.ngo_user_id
 OR (SELECT count(*) FROM public.claim_reconciliation_evidence WHERE case_id=rc.case_id)<>2
 OR (SELECT count(DISTINCT e.actor_user_id) FROM public.claim_reconciliation_evidence e
     JOIN public.user_profiles u ON u.user_id=e.actor_user_id
     WHERE e.case_id=rc.case_id AND e.handover_confirmed IS TRUE
     AND ((e.actor_user_id=c.ngo_user_id AND u.role='NGO')
       OR (e.actor_user_id=counterpart AND u.role=expected_role)))<>2
 THEN RAISE EXCEPTION 'VALIDATED_TWO_PARTY_HANDOVER_REQUIRED'; END IF;
 -- This hook runs only AFTER the original mixed-batch/custody checks and
 -- donation/inventory collection, immediately before its task UPDATE.
 IF EXISTS(SELECT 1 FROM public.listings l WHERE l.listing_id=lid AND l.source_type='DIRECT_DONATION'
   AND NOT EXISTS(SELECT 1 FROM public.donations d WHERE d.donation_id=l.donation_id AND d.donation_status='COLLECTED'))
 OR EXISTS(SELECT 1 FROM public.listings l JOIN public.hub_batch_members m ON m.batch_id=l.batch_id
   JOIN public.donations d ON d.donation_id=m.donation_id WHERE l.listing_id=lid AND m.membership_status='ACTIVE'
   AND d.donation_status<>'COLLECTED')
 THEN RAISE EXCEPTION 'RECONCILIATION_CUSTODY_NOT_COLLECTED'; END IF;
 SELECT route_id INTO rid FROM routing_private.items WHERE task_id=t.task_id AND released_at IS NULL;
 IF rid IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM routing_private.items i JOIN routing_private.bindings b USING(route_id)
    JOIN public.pickup_routes r USING(route_id)
    WHERE i.route_id=rid AND i.task_id=t.task_id AND b.ngo_id=c.ngo_user_id
    AND b.closed_at IS NULL AND b.started_at IS NOT NULL AND i.consumed_at IS NOT NULL AND i.dispatch_xid IS NOT NULL
    AND r.ngo_user_id=b.ngo_id AND r.vehicle_id=b.vehicle_id AND r.validation_reference=b.candidate_id::text
    AND r.route_status='IN_PROGRESS') THEN RAISE EXCEPTION 'RECONCILIATION_ROUTE_REQUIRES_REVIEW'; END IF;
  UPDATE routing_private.items SET complete_xid=pg_current_xact_id() WHERE route_id=rid AND task_id=t.task_id;
 ELSIF t.task_status='DISPATCHED' THEN
  UPDATE routing_private.legacy_inflight SET complete_xid=pg_current_xact_id() WHERE task_id=t.task_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'RECONCILIATION_TASK_NOT_CAPTURED_AT_CUTOVER'; END IF;
 END IF;
END

DECLARE tid uuid;
BEGIN
 IF NOT routing_private.reconciliation_participant(p_claim) THEN RAISE EXCEPTION 'RECONCILIATION_PARTICIPANT_ONLY'; END IF;
 SELECT t.task_id INTO tid FROM public.pickup_tasks t
 JOIN public.donation_claims c USING(claim_id) JOIN public.claim_leases le USING(claim_id)
 JOIN public.claim_reconciliation_cases rc USING(claim_id)
 WHERE t.claim_id=p_claim AND t.task_status='COLLECTED' AND c.claim_status='COMPLETED'
 AND le.lease_status='COMPLETED' AND rc.case_status='RESOLVED_COLLECTED';
 IF tid IS NULL THEN RAISE EXCEPTION 'RECONCILIATION_NOT_RESOLVED_COLLECTED'; END IF;
 UPDATE routing_private.items SET collected_at=coalesce(collected_at,clock_timestamp())
 WHERE task_id=tid AND released_at IS NULL AND complete_xid=pg_current_xact_id();
 IF EXISTS(SELECT 1 FROM routing_private.items WHERE task_id=tid AND released_at IS NULL AND collected_at IS NULL)
 THEN RAISE EXCEPTION 'RECONCILIATION_ROUTE_BOOKKEEPING_FAILED'; END IF;
 -- No assignment deletion, route closure, vehicle edit, release or dispatch.
END

DECLARE ngo uuid:=auth.uid(); prior routing_private.requests%rowtype;
BEGIN
 IF ngo IS NULL THEN RAISE EXCEPTION 'UNAUTHENTICATED'; END IF;
 -- Same identity/role/active conditions; receipt reads take no writer row locks.
 IF NOT EXISTS(SELECT 1 FROM public.ngo_profiles n JOIN public.user_profiles u
   ON u.user_id=n.user_id AND u.role=n.role
   WHERE n.user_id=ngo AND n.active_flag AND n.role='NGO')
 THEN RAISE EXCEPTION 'ACTIVE_NGO_PROFILE_REQUIRED'; END IF;
 IF p_request IS NULL THEN RAISE EXCEPTION 'REQUEST_REQUIRED'; END IF;
 SELECT r.* INTO prior FROM routing_private.requests r
 WHERE r.ngo_id=ngo AND r.request_id=p_request AND r.operation='AUTHORIZE';
 IF NOT FOUND THEN RETURN jsonb_build_object('contract','geolock.routing-auto-now.v1',
   'ngo_id',ngo,'request_id',p_request,'outcome','NOT_FOUND'); END IF;
 RETURN jsonb_build_object('contract','geolock.routing-auto-now.v1','ngo_id',ngo,
   'request_id',p_request,'outcome','FOUND','result',prior.result);
END;

 BEGIN
 IF NOT (SELECT enabled FROM resolution_private.config WHERE singleton) THEN RAISE EXCEPTION 'ROUTE_RESOLUTION_DISABLED'; END IF;
END

 BEGIN
 PERFORM resolution_private.operator_key();
 RETURN (SELECT jsonb_build_object('case',to_jsonb(c),'items',(SELECT coalesce(jsonb_agg(to_jsonb(i)),'[]') FROM resolution_private.items i WHERE i.case_id=p_case),'evidence',(SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.version),'[]') FROM resolution_private.evidence e WHERE e.case_id=p_case),'incidents',(SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.created_at),'[]') FROM resolution_private.incidents e WHERE e.case_id=p_case)) FROM resolution_private.cases c WHERE c.case_id=p_case);
END

DECLARE actor uuid;role_name text;principal text;label text;BEGIN
 IF EXISTS(SELECT 1 FROM resolution_private.operators WHERE login_name=session_user) THEN
  PERFORM resolution_private.operator_key();
  principal:=session_user::text;
  SELECT operator_label INTO STRICT label FROM resolution_private.operators WHERE login_name=session_user AND active;
  actor:=NULL;role_name:='SYSTEM';
 ELSE
  actor:=auth.uid();role_name:=CASE WHEN actor IS NULL THEN 'SYSTEM' ELSE (SELECT role FROM public.user_profiles WHERE user_id=actor) END;
 END IF;
 INSERT INTO public.audit_events(actor_user_id,actor_role,entity_type,entity_id,event_type,request_id,outcome,details)
 VALUES(actor,role_name,'ROUTE',p_route,p_event,p_request,'SUCCESS',p_details||jsonb_build_object('case_id',p_case,'operator_principal',principal,'operator_label',label,'transaction_id',pg_current_xact_id()::text));
END

 BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.user_profiles WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'AUTHENTICATION_REQUIRED'; END IF;
 RETURN 'user:'||auth.uid()::text;
END

DECLARE r resolution_private.requests%rowtype; BEGIN
 IF p_request IS NULL THEN RAISE EXCEPTION 'REQUEST_REQUIRED'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('route-resolution-request:'||p_actor||':'||p_request,0));
 SELECT * INTO r FROM resolution_private.requests WHERE actor_key=p_actor AND request_id=p_request;
 IF FOUND THEN
  IF r.operation<>p_operation OR r.payload_digest<>routing_private.hash(p_payload) THEN RAISE EXCEPTION 'REQUEST_PAYLOAD_CONFLICT'; END IF;
  RETURN r.result;
 END IF; RETURN NULL;
END

 BEGIN
 INSERT INTO resolution_private.requests VALUES(p_actor,p_request,p_operation,routing_private.hash(p_payload),p_result); RETURN p_result;
END

DECLARE r resolution_private.test_runs%rowtype; rid uuid; BEGIN
 -- Also cover existing donation-transition audit helpers used by finalization.
 IF EXISTS(SELECT 1 FROM resolution_private.operators WHERE login_name=session_user) THEN
  PERFORM resolution_private.operator_key();
  NEW.actor_user_id:=NULL;NEW.actor_role:='SYSTEM';
  NEW.details:=coalesce(NEW.details,'{}')||jsonb_build_object('operator_principal',session_user::text,
   'operator_label',(SELECT operator_label FROM resolution_private.operators WHERE login_name=session_user AND active));
 END IF;
 IF NEW.details ? 'simulation' OR NEW.details ? 'test_run_id' OR NEW.details ? 'test_manifest_digest' THEN RAISE EXCEPTION 'CLIENT_TEST_PROVENANCE_FORBIDDEN'; END IF;
 rid:=CASE WHEN NEW.entity_type='ROUTE' THEN NEW.entity_id ELSE NULL END;
 SELECT tr.* INTO r FROM resolution_private.test_runs tr WHERE
 (NEW.claim_id=ANY(tr.fixture_claim_ids)) OR (rid IS NOT NULL AND EXISTS(
 SELECT 1 FROM routing_private.bindings b WHERE b.route_id=rid AND b.ngo_id=tr.ngo_id AND b.vehicle_id=tr.vehicle_id
 AND NOT EXISTS(SELECT 1 FROM routing_private.items i JOIN public.pickup_tasks t USING(task_id) WHERE i.route_id=rid AND NOT(t.claim_id=ANY(tr.fixture_claim_ids))))) LIMIT 1;
 IF FOUND THEN NEW.details:=coalesce(NEW.details,'{}')||jsonb_build_object('simulation',true,'test_run_id',r.run_id,'test_manifest_digest',r.manifest_digest); END IF;
 RETURN NEW;
END

DECLARE c resolution_private.cases%rowtype;b routing_private.bindings%rowtype;ids uuid[];BEGIN
 SELECT * INTO STRICT c FROM resolution_private.cases WHERE case_id=p_case;
 SELECT * INTO STRICT b FROM routing_private.bindings WHERE route_id=c.route_id;
 PERFORM 1 FROM public.ngo_profiles WHERE user_id=c.ngo_id FOR SHARE;
 PERFORM pg_advisory_xact_lock(hashtextextended('routing-ngo:'||c.ngo_id::text,0));
 SELECT array_agg(task_id ORDER BY task_id) INTO ids FROM routing_private.items WHERE route_id=c.route_id;
 PERFORM routing_private.lock_sources(ids);
 PERFORM 1 FROM public.vehicles WHERE vehicle_id=b.vehicle_id FOR UPDATE;
 PERFORM 1 FROM public.pickup_routes WHERE route_id=c.route_id FOR UPDATE;
 PERFORM 1 FROM public.pickup_tasks WHERE task_id=ANY(ids) ORDER BY task_id FOR UPDATE;
 PERFORM 1 FROM routing_private.bindings WHERE route_id=c.route_id FOR UPDATE;
 SELECT * INTO STRICT c FROM resolution_private.cases WHERE case_id=p_case FOR UPDATE;
 RETURN c;
END

DECLARE ids uuid[];b routing_private.bindings%rowtype;BEGIN
 SELECT * INTO b FROM routing_private.bindings WHERE route_id=p_route;
 SELECT array_agg(t.claim_id ORDER BY t.claim_id) INTO ids FROM routing_private.items i JOIN public.pickup_tasks t USING(task_id) WHERE i.route_id=p_route;
 IF EXISTS(SELECT 1 FROM resolution_private.test_runs WHERE fixture_claim_ids && ids) AND NOT EXISTS(SELECT 1 FROM resolution_private.test_runs WHERE ngo_id=b.ngo_id AND vehicle_id=b.vehicle_id AND ids <@ fixture_claim_ids) THEN RAISE EXCEPTION 'MIXED_SYNTHETIC_ROUTE_FORBIDDEN'; END IF;
END

DECLARE rid uuid;BEGIN
 IF NEW.task_status IS DISTINCT FROM OLD.task_status THEN
  SELECT route_id INTO rid FROM routing_private.items WHERE task_id=OLD.task_id AND released_at IS NULL;
  IF rid IS NOT NULL THEN PERFORM resolution_private.assert_test_scope(rid); END IF;
 END IF;RETURN NEW;
END

DECLARE actor text:=resolution_private.actor_key();payload jsonb:=jsonb_build_object('case',p_case,'task',p_task,'assertion',p_assertion,'version',p_version);prior jsonb;c resolution_private.cases%rowtype;i resolution_private.items%rowtype; old_assertion text; lock_claim uuid;
BEGIN
 PERFORM resolution_private.require_enabled();
 IF NOT resolution_private.allowed(p_case,auth.uid()) THEN RAISE EXCEPTION 'RESOLUTION_PARTICIPANT_ONLY'; END IF;
 prior:=resolution_private.receipt(actor,p_request,'EVIDENCE',payload);IF prior IS NOT NULL THEN RETURN prior;END IF;
 SELECT * INTO STRICT c FROM resolution_private.cases WHERE case_id=p_case;
 -- Choose an authorized participant anchor; the unchanged helper still locks
 -- the complete managed route in its existing source/vehicle/route order.
 IF p_task IS NULL THEN
  IF auth.uid()<>c.ngo_id OR p_assertion<>'VEHICLE_RETURNED_TO_NGO_CONTROL' THEN RAISE EXCEPTION 'NGO_VEHICLE_CONFIRMATION_REQUIRED'; END IF;
  SELECT claim_id INTO STRICT lock_claim FROM resolution_private.items WHERE case_id=p_case ORDER BY task_id LIMIT 1;
 ELSE
  SELECT * INTO STRICT i FROM resolution_private.items WHERE case_id=p_case AND task_id=p_task;
  IF auth.uid() NOT IN(c.ngo_id,i.source_actor) OR NOT EXISTS(SELECT 1 FROM public.user_profiles WHERE user_id=auth.uid() AND role=CASE WHEN auth.uid()=c.ngo_id THEN 'NGO' ELSE i.source_role END) THEN RAISE EXCEPTION 'ITEM_PARTICIPANT_ONLY'; END IF;
  lock_claim:=i.claim_id;
 END IF;
 PERFORM routing_private.lock_reconciliation_scope(lock_claim);
 SELECT * INTO STRICT c FROM resolution_private.cases WHERE case_id=p_case FOR UPDATE;
 IF c.resolved_at IS NOT NULL THEN RAISE EXCEPTION 'TERMINAL_RESOLUTION_IMMUTABLE'; END IF;
 IF p_version IS DISTINCT FROM c.version THEN RAISE EXCEPTION 'CASE_VERSION_STALE'; END IF;
 IF p_task IS NULL THEN
  IF auth.uid()<>c.ngo_id OR p_assertion<>'VEHICLE_RETURNED_TO_NGO_CONTROL' THEN RAISE EXCEPTION 'NGO_VEHICLE_CONFIRMATION_REQUIRED'; END IF;
 ELSE
  SELECT * INTO STRICT i FROM resolution_private.items WHERE case_id=p_case AND task_id=p_task;
  IF auth.uid() NOT IN(c.ngo_id,i.source_actor) OR NOT EXISTS(SELECT 1 FROM public.user_profiles WHERE user_id=auth.uid() AND role=CASE WHEN auth.uid()=c.ngo_id THEN 'NGO' ELSE i.source_role END) THEN RAISE EXCEPTION 'ITEM_PARTICIPANT_ONLY'; END IF;
  IF p_assertion IS NULL OR p_assertion NOT IN('NO_HANDOVER_SOURCE_RETAINS_GOODS','HANDOVER_TO_NGO_CONFIRMED','UNKNOWN_CUSTODY') THEN RAISE EXCEPTION 'CUSTODY_ASSERTION_REQUIRED'; END IF;
  IF p_assertion='HANDOVER_TO_NGO_CONFIRMED' AND i.initial_class='NEVER_STARTED' THEN RAISE EXCEPTION 'NEVER_STARTED_HANDOVER_FORBIDDEN'; END IF;
 END IF;
 old_assertion:=resolution_private.latest(p_case,p_task,auth.uid());
 UPDATE resolution_private.cases SET version=version+1,status=CASE WHEN p_assertion='UNKNOWN_CUSTODY' OR (old_assertion IS NOT NULL AND old_assertion<>p_assertion)
 OR (p_task IS NOT NULL AND resolution_private.latest(p_case,p_task,CASE WHEN auth.uid()=c.ngo_id THEN i.source_actor ELSE c.ngo_id END) IS NOT NULL
 AND resolution_private.latest(p_case,p_task,CASE WHEN auth.uid()=c.ngo_id THEN i.source_actor ELSE c.ngo_id END)<>p_assertion)
 THEN 'MANUAL_REVIEW' ELSE 'AWAITING_EVIDENCE' END WHERE case_id=p_case RETURNING * INTO c;
 INSERT INTO resolution_private.evidence(case_id,task_id,actor_id,assertion,version) VALUES(p_case,p_task,auth.uid(),p_assertion,c.version);
 IF p_task IS NOT NULL AND p_assertion='HANDOVER_TO_NGO_CONFIRMED' THEN
  PERFORM public.submit_claim_reconciliation(i.claim_id,true,p_request);
 END IF;
 PERFORM resolution_private.audit(c.route_id,p_case,CASE WHEN old_assertion IS NOT NULL THEN 'ROUTE_RESOLUTION_EVIDENCE_SUPERSEDED' ELSE 'ROUTE_RESOLUTION_EVIDENCE_SUBMITTED' END,p_request,jsonb_build_object('task_id',p_task,'assertion',p_assertion,'version',c.version));
 RETURN resolution_private.save_receipt(actor,p_request,'EVIDENCE',payload,jsonb_build_object('case_id',p_case,'version',c.version,'status',c.status));
END

DECLARE actor text:=resolution_private.actor_key();payload jsonb:=jsonb_build_object('case',p_case,'task',p_task,'assertion',p_assertion);prior jsonb;c resolution_private.cases%rowtype;incident uuid;
BEGIN
 PERFORM resolution_private.require_enabled();
 IF NOT resolution_private.allowed(p_case,auth.uid()) THEN RAISE EXCEPTION 'RESOLUTION_PARTICIPANT_ONLY'; END IF;
 prior:=resolution_private.receipt(actor,p_request,'INCIDENT',payload);IF prior IS NOT NULL THEN RETURN prior;END IF;
 SELECT * INTO STRICT c FROM resolution_private.cases WHERE case_id=p_case FOR SHARE;
 IF c.status<>'RESOLVED' OR c.resolved_at IS NULL THEN RAISE EXCEPTION 'TERMINAL_CASE_REQUIRED'; END IF;
 IF p_assertion IS NULL OR p_assertion NOT IN('NO_HANDOVER_SOURCE_RETAINS_GOODS','HANDOVER_TO_NGO_CONFIRMED','UNKNOWN_CUSTODY') THEN RAISE EXCEPTION 'CUSTODY_ASSERTION_REQUIRED'; END IF;
 IF p_task IS NULL OR NOT EXISTS(SELECT 1 FROM resolution_private.items i WHERE i.case_id=p_case AND i.task_id=p_task AND (c.ngo_id=auth.uid() OR i.source_actor=auth.uid())) THEN RAISE EXCEPTION 'ITEM_PARTICIPANT_ONLY'; END IF;
 INSERT INTO resolution_private.incidents(case_id,task_id,actor_id,assertion,case_version) VALUES(p_case,p_task,auth.uid(),p_assertion,c.version) RETURNING incident_id INTO incident;
 PERFORM resolution_private.audit(c.route_id,p_case,'ROUTE_RESOLUTION_INCIDENT_REPORTED',p_request,jsonb_build_object('incident_id',incident,'task_id',p_task,'assertion',p_assertion));
 RETURN resolution_private.save_receipt(actor,p_request,'INCIDENT',payload,jsonb_build_object('case_id',p_case,'incident_id',incident,'status','INCIDENT_RECORDED','route_id',c.route_id));
END

 BEGIN
 PERFORM resolution_private.actor_key();
 RETURN jsonb_build_object('contract','geolock.route-resolution.v1','cases',(SELECT coalesce(jsonb_agg(jsonb_build_object('case_id',c.case_id,'route_id',c.route_id,'status',c.status,'version',c.version) ORDER BY c.created_at DESC),'[]') FROM resolution_private.cases c WHERE resolution_private.allowed(c.case_id,auth.uid())));
END

DECLARE c resolution_private.cases%rowtype;is_owner boolean;BEGIN
 PERFORM resolution_private.actor_key();
 SELECT * INTO c FROM resolution_private.cases WHERE route_id=p_route;
 IF NOT FOUND THEN
  IF NOT EXISTS(SELECT 1 FROM routing_private.bindings WHERE route_id=p_route AND ngo_id=auth.uid()) THEN RAISE EXCEPTION 'NOT_ROUTE_OWNER'; END IF;
  RETURN jsonb_build_object('contract','geolock.route-resolution.v1','route_id',p_route,'status','NOT_REPORTED','enabled',(SELECT enabled FROM resolution_private.config WHERE singleton))||coalesce(resolution_private.test_metadata(p_route),'{}');
 END IF;
 IF NOT resolution_private.allowed(c.case_id,auth.uid()) THEN RAISE EXCEPTION 'RESOLUTION_PARTICIPANT_ONLY'; END IF;
 is_owner:=auth.uid()=c.ngo_id;
 RETURN jsonb_build_object('contract','geolock.route-resolution.v1','route_id',p_route,'case_id',c.case_id,'version',c.version,'status',c.status,'enabled',(SELECT enabled FROM resolution_private.config WHERE singleton),
 'is_owner',is_owner,'vehicle_confirmed',CASE WHEN is_owner THEN resolution_private.latest(c.case_id,NULL,c.ngo_id)='VEHICLE_RETURNED_TO_NGO_CONTROL' END,
 'items',(SELECT coalesce(jsonb_agg(jsonb_build_object('task_id',i.task_id,'claim_id',i.claim_id,'initial_class',i.initial_class,'my_assertion',resolution_private.latest(c.case_id,i.task_id,auth.uid()),'ngo_assertion',resolution_private.latest(c.case_id,i.task_id,c.ngo_id),'source_assertion',resolution_private.latest(c.case_id,i.task_id,i.source_actor)) ORDER BY i.task_id),'[]') FROM resolution_private.items i WHERE i.case_id=c.case_id AND (is_owner OR i.source_actor=auth.uid())))||coalesce(resolution_private.test_metadata(p_route),'{}');
END

DECLARE actor text:=resolution_private.actor_key(); payload jsonb:=jsonb_build_object('route',p_route,'reason',p_reason); prior jsonb;

 b routing_private.bindings%rowtype;c resolution_private.cases%rowtype;x record;counterpart uuid;source_role text;

BEGIN

 PERFORM resolution_private.require_enabled();

 IF NOT EXISTS(SELECT 1 FROM public.user_profiles WHERE user_id=auth.uid() AND role='NGO') THEN RAISE EXCEPTION 'NGO_ROLE_REQUIRED'; END IF;

 IF NOT EXISTS(SELECT 1 FROM routing_private.bindings WHERE route_id=p_route AND ngo_id=auth.uid()) THEN RAISE EXCEPTION 'NOT_ROUTE_OWNER'; END IF;

 prior:=resolution_private.receipt(actor,p_request,'REPORT',payload); IF prior IS NOT NULL THEN RETURN prior; END IF;

 b:=routing_private.lock_route(p_route,false);

 PERFORM resolution_private.assert_test_scope(p_route);

 IF p_reason IS NULL OR p_reason NOT IN('EXECUTION_BUDGET_EXCEEDED','VEHICLE_FAILURE','PICKUP_UNAVAILABLE','OTHER_REQUIRES_REVIEW') THEN RAISE EXCEPTION 'INTERRUPTION_REASON_REQUIRED'; END IF;

 IF b.started_at IS NULL OR b.closed_at IS NOT NULL OR (SELECT route_status FROM public.pickup_routes WHERE route_id=p_route)<>'IN_PROGRESS' THEN RAISE EXCEPTION 'STARTED_OPEN_ROUTE_REQUIRED'; END IF;

 SELECT * INTO c FROM resolution_private.cases WHERE route_id=p_route FOR UPDATE;

 IF NOT FOUND THEN RAISE EXCEPTION 'NEW_ROUTE_INTERRUPTION_REPORTS_RETIRED'; END IF;
 IF false THEN

  INSERT INTO resolution_private.cases(route_id,ngo_id,status,reason,manifest_digest) VALUES(p_route,b.ngo_id,'AWAITING_EVIDENCE',p_reason,resolution_private.manifest(p_route)) RETURNING * INTO c;

  FOR x IN SELECT t.*,i.consumed_at,i.collected_at,l.source_type,l.donation_id,l.batch_id FROM routing_private.items i JOIN public.pickup_tasks t USING(task_id) JOIN public.listings l USING(listing_id) WHERE i.route_id=p_route ORDER BY i.ordinal LOOP

   SELECT CASE WHEN x.source_type='DIRECT_DONATION' THEN d.donor_user_id ELSE h.admin_user_id END INTO counterpart

   FROM public.listings l LEFT JOIN public.donations d ON d.donation_id=l.donation_id LEFT JOIN public.hub_batches hb ON hb.batch_id=l.batch_id LEFT JOIN public.community_hubs h ON h.hub_id=hb.hub_id WHERE l.listing_id=x.listing_id;

   source_role:=CASE WHEN x.source_type='DIRECT_DONATION' THEN 'DONOR' ELSE 'HUB_ADMIN' END;

   IF counterpart IS NULL OR counterpart=b.ngo_id OR NOT EXISTS(SELECT 1 FROM public.user_profiles WHERE user_id=counterpart AND role=source_role) THEN RAISE EXCEPTION 'SOURCE_PARTICIPANT_REQUIRED'; END IF;

   IF x.task_status='COLLECTED' AND x.collected_at IS NOT NULL THEN

    IF NOT EXISTS(SELECT 1 FROM public.donation_claims dc JOIN public.claim_leases le USING(claim_id) WHERE dc.claim_id=x.claim_id AND dc.claim_status='COMPLETED' AND le.lease_status='COMPLETED') THEN RAISE EXCEPTION 'COLLECTED_STATE_INCONSISTENT'; END IF;

   ELSE

    IF x.task_status NOT IN('PLANNED','DISPATCHED') OR (x.task_status='PLANNED' AND x.consumed_at IS NOT NULL) OR (x.task_status='DISPATCHED' AND x.consumed_at IS NULL) THEN RAISE EXCEPTION 'ITEM_CLASSIFICATION_INCONSISTENT'; END IF;

    IF NOT EXISTS(SELECT 1 FROM public.donation_claims dc JOIN public.claim_leases le USING(claim_id) WHERE dc.claim_id=x.claim_id AND dc.claim_status IN('ACTIVE','RECONCILIATION_REQUIRED') AND le.lease_status IN('ACTIVE','RECONCILIATION_REQUIRED')) THEN RAISE EXCEPTION 'CLAIM_RESOLUTION_STATE_MISMATCH'; END IF;

    UPDATE public.donation_claims SET claim_status='RECONCILIATION_REQUIRED' WHERE claim_id=x.claim_id;

    UPDATE public.claim_leases SET lease_status='RECONCILIATION_REQUIRED' WHERE claim_id=x.claim_id;

    IF NOT EXISTS(SELECT 1 FROM public.claim_reconciliation_cases WHERE claim_id=x.claim_id AND case_status IN('OPEN','MANUAL_REVIEW')) THEN

     INSERT INTO public.claim_reconciliation_cases(claim_id,listing_id,donation_id,source_type,case_status) VALUES(x.claim_id,x.listing_id,x.donation_id,x.source_type,'OPEN');

    END IF;

   END IF;

   INSERT INTO resolution_private.items VALUES(c.case_id,x.task_id,x.claim_id,counterpart,source_role,CASE WHEN x.collected_at IS NOT NULL THEN 'COLLECTED' WHEN x.consumed_at IS NOT NULL THEN 'DISPATCHED' ELSE 'NEVER_STARTED' END,routing_private.task_digest(routing_private.observe_task(x.task_id)));

  END LOOP;

  PERFORM resolution_private.audit(p_route,c.case_id,'ROUTE_INTERRUPTION_REPORTED',p_request,jsonb_build_object('reason',p_reason));

 END IF;

 RETURN resolution_private.save_receipt(actor,p_request,'REPORT',payload,jsonb_build_object('contract','geolock.route-resolution.v1','case_id',c.case_id,'route_id',p_route,'version',c.version,'status',c.status));

END

DECLARE actor text:=resolution_private.operator_key();payload jsonb:=jsonb_build_object('case',p_case,'version',p_version);prior jsonb;
 c resolution_private.cases%rowtype;b routing_private.bindings%rowtype;x record;obs jsonb;d jsonb;counterpart uuid;blocked text;result jsonb;
BEGIN
 PERFORM resolution_private.require_enabled(); prior:=resolution_private.receipt(actor,p_request,'FINALIZE',payload);IF prior IS NOT NULL THEN RETURN prior;END IF;
 c:=resolution_private.lock_case(p_case);
 PERFORM resolution_private.assert_test_scope(c.route_id);
 IF c.resolved_at IS NOT NULL THEN RAISE EXCEPTION 'TERMINAL_RESOLUTION_IMMUTABLE'; END IF;
 IF c.version IS DISTINCT FROM p_version THEN RAISE EXCEPTION 'CASE_VERSION_STALE'; END IF;
 SELECT * INTO STRICT b FROM routing_private.bindings WHERE route_id=c.route_id;
 IF b.closed_at IS NOT NULL OR b.started_at IS NULL OR resolution_private.manifest(c.route_id)<>c.manifest_digest
 OR (SELECT route_status FROM public.pickup_routes WHERE route_id=c.route_id)<>'IN_PROGRESS'
 OR NOT EXISTS(SELECT 1 FROM public.vehicles WHERE vehicle_id=b.vehicle_id AND ngo_user_id=c.ngo_id AND vehicle_version=b.vehicle_version)
 OR EXISTS(SELECT 1 FROM public.pickup_routes r WHERE r.route_id=c.route_id AND (r.vehicle_id<>b.vehicle_id OR r.ngo_user_id<>c.ngo_id OR r.validation_reference<>b.candidate_id::text))
 THEN RAISE EXCEPTION 'RESOLUTION_BINDING_DRIFT'; END IF;
 IF resolution_private.latest(p_case,NULL,c.ngo_id) IS DISTINCT FROM 'VEHICLE_RETURNED_TO_NGO_CONTROL' THEN RAISE EXCEPTION 'VEHICLE_ACCOUNTABILITY_REQUIRED'; END IF;
 FOR x IN SELECT ri.*,t.task_status,t.listing_id,it.consumed_at,it.collected_at FROM resolution_private.items ri JOIN public.pickup_tasks t USING(task_id) JOIN routing_private.items it ON it.task_id=t.task_id AND it.route_id=c.route_id WHERE ri.case_id=p_case ORDER BY it.ordinal LOOP
  obs:=routing_private.observe_task(x.task_id);
  IF obs IS NULL OR jsonb_array_length(obs->'donations')=0 THEN RAISE EXCEPTION 'SOURCE_SET_MISSING'; END IF;
  IF x.task_status='COLLECTED' AND x.collected_at IS NOT NULL AND obs->'claim'->>'claim_status'='COMPLETED' AND obs->'lease'->>'lease_status'='COMPLETED'
  AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(obs->'donations') z WHERE z->>'donation_status'<>'COLLECTED') THEN
   IF EXISTS(SELECT 1 FROM (SELECT DISTINCT ON(actor_id) assertion FROM resolution_private.evidence WHERE case_id=p_case AND task_id=x.task_id ORDER BY actor_id,version DESC) latest WHERE assertion<>'HANDOVER_TO_NGO_CONFIRMED') THEN RAISE EXCEPTION 'COLLECTED_CUSTODY_DISPUTED'; END IF;
   CONTINUE;
  END IF;
  IF x.initial_class='COLLECTED' THEN RAISE EXCEPTION 'COLLECTED_STATE_INCONSISTENT'; END IF;
  IF resolution_private.latest(p_case,x.task_id,c.ngo_id) IS DISTINCT FROM 'NO_HANDOVER_SOURCE_RETAINS_GOODS'
  OR resolution_private.latest(p_case,x.task_id,x.source_actor) IS DISTINCT FROM 'NO_HANDOVER_SOURCE_RETAINS_GOODS' THEN RAISE EXCEPTION 'MATCHING_TWO_PARTY_NO_HANDOVER_REQUIRED'; END IF;
  SELECT CASE WHEN l.source_type='DIRECT_DONATION' THEN dn.donor_user_id ELSE h.admin_user_id END INTO counterpart
  FROM public.listings l LEFT JOIN public.donations dn ON dn.donation_id=l.donation_id LEFT JOIN public.hub_batches hb ON hb.batch_id=l.batch_id LEFT JOIN public.community_hubs h ON h.hub_id=hb.hub_id WHERE l.listing_id=x.listing_id;
  IF counterpart IS DISTINCT FROM x.source_actor OR counterpart=c.ngo_id OR NOT EXISTS(SELECT 1 FROM public.user_profiles WHERE user_id=x.source_actor AND role=x.source_role) THEN RAISE EXCEPTION 'SOURCE_PARTICIPANT_DRIFT'; END IF;
  IF routing_private.task_digest(obs)<>x.observation_digest OR obs->'claim'->>'claim_status'<>'RECONCILIATION_REQUIRED'
  OR obs->'lease'->>'lease_status'<>'RECONCILIATION_REQUIRED' OR x.task_status NOT IN('PLANNED','DISPATCHED')
  OR NOT EXISTS(SELECT 1 FROM public.active_task_route_assignments WHERE task_id=x.task_id AND route_id=c.route_id)
  OR EXISTS(SELECT 1 FROM public.claim_reconciliation_evidence e JOIN public.claim_reconciliation_cases rc USING(case_id) WHERE rc.claim_id=x.claim_id AND e.handover_confirmed)
  THEN RAISE EXCEPTION 'CUSTODY_OR_OBSERVATION_CONFLICT'; END IF;
  IF obs->'listing'->>'listing_status'<>'CLAIMED' OR (obs->'listing'->>'listing_expires_at')::timestamptz<=clock_timestamp()
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(obs->'donations') z WHERE (z->>'availability_end')::timestamptz<=clock_timestamp()) THEN blocked:='UNSAFE_LISTING_VALIDITY'; END IF;
  IF jsonb_array_length(obs->'donations')=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(obs->'donations') z WHERE z->>'donation_status'<>CASE WHEN x.initial_class='DISPATCHED' THEN 'PICKUP_IN_PROGRESS' ELSE 'CLAIMED' END) THEN RAISE EXCEPTION 'SOURCE_CUSTODY_STATE_MISMATCH'; END IF;
 END LOOP;
 IF blocked IS NOT NULL THEN
  UPDATE resolution_private.cases SET status='MANUAL_REVIEW',version=version+1 WHERE case_id=p_case RETURNING * INTO c;
  PERFORM resolution_private.audit(c.route_id,p_case,'ROUTE_RESOLUTION_REVIEW_REQUIRED',p_request,jsonb_build_object('reason',blocked));
  RETURN resolution_private.save_receipt(actor,p_request,'FINALIZE',payload,jsonb_build_object('case_id',p_case,'status','MANUAL_REVIEW','reason',blocked,'version',c.version));
 END IF;
 FOR x IN SELECT ri.*,t.task_status,t.listing_id,l.source_type,it.collected_at FROM resolution_private.items ri JOIN public.pickup_tasks t USING(task_id) JOIN public.listings l USING(listing_id) JOIN routing_private.items it ON it.task_id=t.task_id AND it.route_id=c.route_id WHERE ri.case_id=p_case ORDER BY it.ordinal LOOP
  INSERT INTO resolution_private.releases SELECT p_case,x.task_id,to_jsonb(a),CASE WHEN x.task_status='COLLECTED' THEN 'RETAINED_COLLECTED' ELSE 'NO_HANDOVER_RELEASED' END,clock_timestamp() FROM public.active_task_route_assignments a WHERE a.task_id=x.task_id AND a.route_id=c.route_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'ACTIVE_ASSIGNMENT_MISSING'; END IF;
  IF x.task_status<>'COLLECTED' THEN
   INSERT INTO resolution_private.permits VALUES(x.task_id,p_case,pg_current_xact_id()) ON CONFLICT(task_id) DO UPDATE SET case_id=excluded.case_id,transaction_id=excluded.transaction_id;
   PERFORM public.geolock_transition_listing_donations(x.listing_id,CASE WHEN x.initial_class='DISPATCHED' THEN 'PICKUP_IN_PROGRESS' ELSE 'CLAIMED' END,CASE WHEN x.source_type='DIRECT_DONATION' THEN 'AVAILABLE' ELSE 'BATCHED' END,x.claim_id,p_request,'ROUTE_RESOLUTION_NO_HANDOVER');
   UPDATE public.pickup_tasks SET task_status='STALE' WHERE task_id=x.task_id;
   UPDATE public.donation_claims SET claim_status='RELEASED',closed_at=clock_timestamp(),close_reason='ROUTE_INTERRUPTED_NO_HANDOVER' WHERE claim_id=x.claim_id;
   UPDATE public.claim_leases SET lease_status='RELEASED',closed_at=clock_timestamp(),release_reason='ROUTE_INTERRUPTED_NO_HANDOVER' WHERE claim_id=x.claim_id;
   UPDATE public.listings SET listing_status='AVAILABLE',listing_version=listing_version+1 WHERE listing_id=x.listing_id;
   UPDATE public.claim_reconciliation_cases SET case_status='RESOLVED_RELEASED',resolved_at=clock_timestamp(),resolution_reason='ROUTE_INTERRUPTED_NO_HANDOVER' WHERE claim_id=x.claim_id AND case_status IN('OPEN','MANUAL_REVIEW');
   PERFORM resolution_private.audit(c.route_id,p_case,'CLAIM_RESOLVED_NO_HANDOVER',p_request,jsonb_build_object('claim_id',x.claim_id,'task_id',x.task_id));
  END IF;
 END LOOP;
 DELETE FROM public.active_task_route_assignments WHERE route_id=c.route_id;
 UPDATE routing_private.items SET released_at=clock_timestamp(),release_xid=pg_current_xact_id() WHERE route_id=c.route_id;
 UPDATE routing_private.bindings SET closed_at=clock_timestamp() WHERE route_id=c.route_id;
 INSERT INTO resolution_private.finalizations VALUES(c.route_id,p_case,pg_current_xact_id());
 UPDATE resolution_private.cases SET status='RESOLVED',resolved_at=clock_timestamp(),version=version+1 WHERE case_id=p_case RETURNING * INTO c;
 UPDATE public.pickup_routes SET route_status='ABANDONED' WHERE route_id=c.route_id;
 PERFORM resolution_private.audit(c.route_id,p_case,'ROUTE_ASSIGNMENTS_RELEASED',p_request,jsonb_build_object('route_manifest_digest',c.manifest_digest));
 PERFORM resolution_private.audit(c.route_id,p_case,'ROUTE_ABANDONED_RECONCILED',p_request,jsonb_build_object('version',c.version));
 result:=jsonb_build_object('contract','geolock.route-resolution.v1','case_id',p_case,'route_id',c.route_id,'status','RESOLVED','route_status','ABANDONED','version',c.version);
 RETURN resolution_private.save_receipt(actor,p_request,'FINALIZE',payload,result);
END

DECLARE actor text:=resolution_private.operator_key(); payload jsonb:=jsonb_build_object('run',p_run,'manifest',p_manifest,'ngo',p_ngo,'vehicle',p_vehicle,'claims',p_claims); prior jsonb; BEGIN
 PERFORM resolution_private.require_enabled(); prior:=resolution_private.receipt(actor,p_request,'TEST_PROVENANCE',payload); IF prior IS NOT NULL THEN RETURN prior; END IF;
 IF p_run IS NULL OR p_manifest IS NULL OR p_manifest!~'^[0-9a-f]{64}$' OR cardinality(p_claims) IS NULL OR cardinality(p_claims)=0
 OR cardinality(p_claims)<>(SELECT count(DISTINCT x) FROM unnest(p_claims) x) OR array_position(p_claims,NULL) IS NOT NULL
 OR NOT EXISTS(SELECT 1 FROM public.vehicles WHERE vehicle_id=p_vehicle AND ngo_user_id=p_ngo)
 OR EXISTS(SELECT 1 FROM unnest(p_claims) x LEFT JOIN public.donation_claims c ON c.claim_id=x WHERE c.claim_id IS NULL OR c.ngo_user_id<>p_ngo)
 OR EXISTS(SELECT 1 FROM resolution_private.test_runs WHERE fixture_claim_ids && p_claims) THEN RAISE EXCEPTION 'INVALID_TEST_PROVENANCE_SCOPE'; END IF;
 INSERT INTO resolution_private.test_runs VALUES(p_run,'rcgyuwiidqvrgbxswhqj',p_manifest,p_ngo,p_vehicle,p_claims,clock_timestamp());
 RETURN resolution_private.save_receipt(actor,p_request,'TEST_PROVENANCE',payload,jsonb_build_object('run_id',p_run,'outcome','REGISTERED'));
END

DECLARE actor text;r jsonb;BEGIN
 IF pg_has_role(session_user,'geolock_route_resolver','MEMBER') THEN actor:=resolution_private.operator_key(); ELSE actor:=resolution_private.actor_key(); END IF;
 IF p_request IS NULL THEN RAISE EXCEPTION 'REQUEST_REQUIRED'; END IF;
 SELECT result INTO r FROM resolution_private.requests WHERE actor_key=actor AND request_id=p_request;
 IF actor LIKE 'user:%' AND r->>'case_id' IS NOT NULL AND NOT resolution_private.allowed((r->>'case_id')::uuid,auth.uid()) THEN RAISE EXCEPTION 'RESOLUTION_PARTICIPANT_ONLY'; END IF;
 RETURN jsonb_build_object('outcome',CASE WHEN r IS NULL THEN 'NOT_FOUND' ELSE 'FOUND' END,'request_id',p_request,'result',r);
END

BEGIN
 IF TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN
  INSERT INTO routing_private.deferred_events(route_id,task_id,claim_id,request_id,status,actor_id)
  VALUES(NEW.route_id,NEW.task_id,NEW.claim_id,NEW.request_id,NEW.status,auth.uid());
 END IF;
 RETURN NEW;
END

DECLARE b routing_private.bindings%rowtype; s routing_private.snapshots%rowtype; m jsonb; pol jsonb; win jsonb; obs jsonb;
 v public.vehicles%rowtype; i record; node text; at_time timestamptz; finish timestamptz; origin timestamptz; first_id uuid;
BEGIN
 SELECT * INTO STRICT b FROM routing_private.bindings WHERE route_id=p_route;
 SELECT sn.* INTO STRICT s FROM routing_private.candidates c JOIN routing_private.snapshots sn USING(snapshot_id) WHERE c.candidate_id=b.candidate_id;
 SELECT body INTO STRICT m FROM routing_private.matrices WHERE matrix_id=s.matrix_id;
 IF NOT EXISTS(SELECT 1 FROM public.pickup_routes r WHERE r.route_id=p_route AND r.ngo_user_id=b.ngo_id AND r.vehicle_id=b.vehicle_id
 AND r.matrix_id=s.matrix_id::text AND r.validation_reference=b.candidate_id::text)
 OR (SELECT count(*) FROM public.pickup_route_stops WHERE route_id=p_route)<>(SELECT count(*) FROM routing_private.items WHERE route_id=p_route)
 OR EXISTS(SELECT 1 FROM routing_private.items x WHERE x.route_id=p_route AND NOT EXISTS(SELECT 1 FROM public.pickup_route_stops z
 WHERE z.route_id=p_route AND z.task_id=x.task_id AND z.stop_order=x.ordinal AND z.ngo_user_id=b.ngo_id))
 THEN RAISE EXCEPTION 'ROUTE_BINDING_DRIFT'; END IF;
 pol:=s.body->'policy'; SELECT * INTO STRICT v FROM public.vehicles WHERE vehicle_id=b.vehicle_id;
 IF b.closed_at IS NOT NULL OR v.vehicle_version<>b.vehicle_version OR NOT v.active_flag OR NOT v.available_for_planning
 OR v.depot_road_node_id IS DISTINCT FROM fleet_private.require_depot(b.ngo_id)
 OR routing_private.ngo_observation(b.ngo_id) IS DISTINCT FROM s.body->'ngo'
 OR (SELECT route_status FROM public.pickup_routes WHERE route_id=p_route) NOT IN ('AUTHORISED','IN_PROGRESS')
 THEN RAISE EXCEPTION 'DISPATCH_AUTHORITY_STALE'; END IF;
 IF EXISTS(SELECT 1 FROM resolution_private.cases c WHERE c.route_id=p_route AND c.status IN ('AWAITING_EVIDENCE','MANUAL_REVIEW')) THEN RAISE EXCEPTION 'WHOLE_ROUTE_INTERRUPTION_REQUIRES_RECONCILIATION'; END IF;
 IF p_now<b.departure_at THEN RAISE EXCEPTION 'BEFORE_AUTHORIZED_DEPARTURE'; END IF;
 IF EXISTS(SELECT 1 FROM routing_private.items x JOIN public.pickup_tasks t USING(task_id) WHERE x.route_id=p_route AND t.task_status='DISPATCHED') THEN RAISE EXCEPTION 'PREVIOUS_PICKUP_UNRESOLVED'; END IF;
 SELECT task_id INTO first_id FROM routing_private.items x WHERE x.route_id=p_route AND x.released_at IS NULL AND x.collected_at IS NULL AND NOT EXISTS(SELECT 1 FROM routing_private.deferred_stops d WHERE d.route_id=x.route_id AND d.task_id=x.task_id AND d.status='DEFERRED') ORDER BY x.ordinal LIMIT 1;
 IF first_id IS DISTINCT FROM p_next THEN RAISE EXCEPTION 'STOP_ORDER_REQUIRED'; END IF;
 node:=v.depot_road_node_id;
 SELECT t.pickup_road_node_id INTO node FROM routing_private.items x JOIN public.pickup_tasks t USING(task_id)
 WHERE x.route_id=p_route AND x.collected_at IS NOT NULL ORDER BY ordinal DESC LIMIT 1;
 node:=coalesce(node,v.depot_road_node_id); at_time:=p_now; origin:=coalesce(b.started_at,p_now);
 FOR i IN SELECT x.* FROM routing_private.items x WHERE x.route_id=p_route AND x.released_at IS NULL AND x.collected_at IS NULL AND NOT EXISTS(SELECT 1 FROM routing_private.deferred_stops d WHERE d.route_id=x.route_id AND d.task_id=x.task_id AND d.status='DEFERRED') ORDER BY x.ordinal LOOP
  obs:=routing_private.observe_task(i.task_id);
  IF routing_private.task_digest(obs) IS DISTINCT FROM i.observation_digest
  OR NOT EXISTS(SELECT 1 FROM public.active_task_route_assignments WHERE task_id=i.task_id AND route_id=p_route)
  THEN RAISE EXCEPTION 'DISPATCH_SOURCE_STALE'; END IF;
  win:=routing_private.task_window(obs,s.cutoff,pol);
  at_time:=at_time+make_interval(secs=>((routing_private.arc(m,node,obs->'task'->>'pickup_road_node_id')->>'minutes')::numeric*60)::double precision);
  at_time:=greatest(at_time,(win->>'start')::timestamptz)+make_interval(secs=>((win->>'service')::numeric*60)::double precision);
  IF at_time>(win->>'end')::timestamptz OR (obs->'lease'->>'expires_at')::timestamptz<=at_time THEN RAISE EXCEPTION 'DISPATCH_WINDOW_OR_LEASE_EXPIRED'; END IF;
  node:=obs->'task'->>'pickup_road_node_id';
 END LOOP;
 finish:=at_time+make_interval(secs=>((routing_private.arc(m,node,v.depot_road_node_id)->>'minutes')::numeric*60)::double precision);
 IF finish>origin+make_interval(secs=>(v.max_route_duration_min*60)::double precision)
 OR finish>s.cutoff+make_interval(secs=>((pol->>'horizon_minutes')::numeric*60)::double precision)
 OR EXISTS(SELECT 1 FROM routing_private.items x JOIN public.pickup_tasks t USING(task_id) JOIN public.claim_leases le USING(claim_id)
 WHERE x.route_id=p_route AND x.released_at IS NULL AND x.collected_at IS NULL AND NOT EXISTS(SELECT 1 FROM routing_private.deferred_stops d WHERE d.route_id=x.route_id AND d.task_id=x.task_id AND d.status='DEFERRED') AND le.expires_at<=finish+make_interval(secs=>((pol->>'dispatch_margin_minutes')::numeric*60)::double precision))
 THEN RAISE EXCEPTION 'REMAINING_ROUTE_INFEASIBLE'; END IF;
END

DECLARE i routing_private.items%rowtype; BEGIN
 IF NEW.task_status=OLD.task_status THEN RETURN NEW; END IF;
 SELECT * INTO i FROM routing_private.items WHERE task_id=OLD.task_id AND (released_at IS NULL OR release_xid=pg_current_xact_id()) ORDER BY released_at NULLS FIRST,ordinal LIMIT 1;
 IF NEW.task_status='DISPATCHED' THEN
  IF i.dispatch_xid IS DISTINCT FROM pg_current_xact_id() OR i.consumed_at IS NULL THEN RAISE EXCEPTION 'DATABASE_DISPATCH_AUTHORIZATION_REQUIRED'; END IF;
 ELSIF NEW.task_status='COLLECTED' THEN
  IF i.complete_xid IS DISTINCT FROM pg_current_xact_id() AND NOT EXISTS(SELECT 1 FROM routing_private.legacy_inflight WHERE task_id=OLD.task_id AND complete_xid=pg_current_xact_id())
  THEN RAISE EXCEPTION 'PROTECTED_COMPLETION_REQUIRED'; END IF;
 ELSIF i.task_id IS NOT NULL THEN
  IF NOT ((OLD.task_status='CONFIRMED' AND NEW.task_status='PLANNED' AND i.planned_xid=pg_current_xact_id())
    OR (OLD.task_status='PLANNED' AND NEW.task_status='CONFIRMED' AND i.release_xid=pg_current_xact_id())
    OR (NEW.task_status='STALE' AND (EXISTS(SELECT 1 FROM public.donation_claims c JOIN public.claim_leases le USING(claim_id) WHERE c.claim_id=OLD.claim_id AND c.claim_status='RECONCILIATION_REQUIRED' AND le.lease_status='RECONCILIATION_REQUIRED') OR EXISTS(SELECT 1 FROM routing_private.deferred_release_permits p WHERE p.task_id=OLD.task_id AND p.transaction_id=pg_current_xact_id()))))
  THEN RAISE EXCEPTION 'RESERVED_TASK_REQUIRES_RECONCILIATION'; END IF;
 END IF;
 RETURN NEW;
END

BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DEFERRED_PICKUP_HISTORY_IMMUTABLE'; END IF;
 IF ROW(NEW.route_id,NEW.task_id,NEW.claim_id,NEW.ngo_id,NEW.request_id,NEW.reason,NEW.deferred_at)
     IS DISTINCT FROM ROW(OLD.route_id,OLD.task_id,OLD.claim_id,OLD.ngo_id,OLD.request_id,OLD.reason,OLD.deferred_at)
  OR OLD.status<>'DEFERRED' OR NEW.status NOT IN('RESOLVED_COLLECTED','RESOLVED_UNCOLLECTED')
  OR NEW.resolved_at IS NULL THEN RAISE EXCEPTION 'INVALID_DEFERRED_PICKUP_TRANSITION'; END IF;
 RETURN NEW;
END

BEGIN
 IF NEW.collected_at IS NOT NULL AND OLD.collected_at IS NULL THEN
  UPDATE routing_private.deferred_stops SET status='RESOLVED_COLLECTED',resolved_at=clock_timestamp()
   WHERE route_id=NEW.route_id AND task_id=NEW.task_id AND status='DEFERRED';
 END IF;
 RETURN NEW;
END

DECLARE ngo uuid:=auth.uid(); b routing_private.bindings%rowtype; payload jsonb; digest text; prior routing_private.mixed_route_closures%rowtype; result jsonb; n integer;
BEGIN
 IF ngo IS NULL OR p_request IS NULL THEN RAISE EXCEPTION 'AUTHENTICATION_AND_REQUEST_REQUIRED'; END IF;
 payload:=jsonb_build_object('route_id',p_route,'depot_return_confirmed',p_depot_return_confirmed); digest:=routing_private.hash(payload);
 PERFORM pg_advisory_xact_lock(hashtextextended('mixed-route-close:'||ngo::text||':'||p_request::text,0));
 SELECT * INTO prior FROM routing_private.mixed_route_closures WHERE ngo_id=ngo AND request_id=p_request;
 IF FOUND THEN IF prior.route_id<>p_route OR prior.payload_digest<>digest THEN RAISE EXCEPTION 'REQUEST_PAYLOAD_CONFLICT'; END IF; RETURN prior.result; END IF;
 b:=routing_private.lock_route(p_route,false);
 IF b.ngo_id IS DISTINCT FROM ngo OR b.closed_at IS NOT NULL OR (SELECT route_status FROM public.pickup_routes WHERE route_id=p_route) NOT IN('AUTHORISED','IN_PROGRESS') THEN RAISE EXCEPTION 'OWNED_ACTIVE_ROUTE_REQUIRED'; END IF;
 IF p_depot_return_confirmed IS DISTINCT FROM true THEN RAISE EXCEPTION 'DEPOT_RETURN_CONFIRMATION_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM resolution_private.cases c WHERE c.route_id=p_route AND c.status IN('AWAITING_EVIDENCE','MANUAL_REVIEW')) THEN RAISE EXCEPTION 'WHOLE_ROUTE_INTERRUPTION_REQUIRES_RECONCILIATION'; END IF;
 IF NOT EXISTS(SELECT 1 FROM routing_private.deferred_stops d WHERE d.route_id=p_route AND d.status='RESOLVED_UNCOLLECTED') THEN RAISE EXCEPTION 'MIXED_OUTCOME_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM routing_private.items i JOIN public.pickup_tasks t USING(task_id) JOIN public.donation_claims c USING(claim_id) JOIN public.claim_leases le USING(claim_id)
   LEFT JOIN routing_private.deferred_stops d ON d.route_id=i.route_id AND d.task_id=i.task_id
   WHERE i.route_id=p_route AND NOT ((i.collected_at IS NOT NULL AND t.task_status='COLLECTED' AND c.claim_status='COMPLETED' AND le.lease_status='COMPLETED')
    OR (d.status='RESOLVED_UNCOLLECTED' AND i.released_at IS NOT NULL AND t.task_status='STALE' AND c.claim_status='RELEASED' AND le.lease_status='RELEASED')))
  THEN RAISE EXCEPTION 'ROUTE_HAS_UNRESOLVED_TASKS'; END IF;
 IF EXISTS(SELECT 1 FROM public.active_task_route_assignments a JOIN public.pickup_tasks t USING(task_id) JOIN routing_private.items i USING(route_id,task_id) WHERE a.route_id=p_route AND NOT(t.task_status='COLLECTED' AND i.collected_at IS NOT NULL)) THEN RAISE EXCEPTION 'ROUTE_ASSIGNMENT_REMAINS'; END IF;
 SELECT count(*) INTO n FROM routing_private.items WHERE route_id=p_route;
 result:=jsonb_build_object('route_id',p_route,'route_status','ABANDONED','outcome','MIXED_OUTCOME','final_pickup_count',n,'request_id',p_request);
 INSERT INTO routing_private.mixed_route_closures(route_id,ngo_id,request_id,payload_digest,transaction_id,result,accountability_confirmed)
 VALUES(p_route,ngo,p_request,digest,pg_current_xact_id(),result,true);
 DELETE FROM public.active_task_route_assignments WHERE route_id=p_route;
 UPDATE routing_private.items SET release_xid=pg_current_xact_id(),released_at=coalesce(released_at,clock_timestamp()) WHERE route_id=p_route;
 UPDATE public.pickup_routes SET route_status='ABANDONED' WHERE route_id=p_route;
 UPDATE routing_private.bindings SET closed_at=clock_timestamp() WHERE route_id=p_route;
 INSERT INTO public.audit_events(actor_user_id,actor_role,entity_type,entity_id,event_type,request_id,outcome,details)
 VALUES(ngo,'NGO','ROUTE',p_route,'CLOSE_MIXED_OUTCOME_ROUTE',p_request,'SUCCESS',jsonb_build_object('final_pickup_count',n,'resolved_uncollected_count',(SELECT count(*) FROM routing_private.deferred_stops WHERE route_id=p_route AND status='RESOLVED_UNCOLLECTED'),'depot_return_confirmed',true,'vehicle_accountability_confirmed',true,'meaning','At least one independently resolved uncollected pickup; every pickup has a valid final outcome.'));
 RETURN result;
END

DECLARE ngo uuid:=auth.uid(); b routing_private.bindings%rowtype; i routing_private.items%rowtype;
 t public.pickup_tasks%rowtype; c public.donation_claims%rowtype; le public.claim_leases%rowtype;
 payload jsonb; digest text; prior routing_private.deferred_requests%rowtype; result jsonb; why text;
BEGIN
 IF ngo IS NULL OR p_request IS NULL THEN RAISE EXCEPTION 'AUTHENTICATION_AND_REQUEST_REQUIRED'; END IF;
 payload:=jsonb_build_object('claim_id',p_claim); digest:=routing_private.hash(payload);
 PERFORM pg_advisory_xact_lock(hashtextextended('defer-pickup:'||ngo::text||':'||p_request::text,0));
 SELECT * INTO prior FROM routing_private.deferred_requests WHERE ngo_id=ngo AND request_id=p_request;
 IF FOUND THEN
  IF prior.payload_digest<>digest OR prior.route_id IS DISTINCT FROM (SELECT route_id FROM routing_private.items WHERE task_id=(SELECT task_id FROM public.pickup_tasks WHERE claim_id=p_claim)) THEN RAISE EXCEPTION 'REQUEST_PAYLOAD_CONFLICT'; END IF;
  RETURN prior.result;
 END IF;
 SELECT x.* INTO STRICT i FROM routing_private.items x JOIN public.pickup_tasks q USING(task_id) WHERE q.claim_id=p_claim AND x.released_at IS NULL;
 b:=routing_private.lock_route(i.route_id);
 SELECT * INTO STRICT t FROM public.pickup_tasks WHERE task_id=i.task_id;
 SELECT * INTO STRICT c FROM public.donation_claims WHERE claim_id=p_claim;
 SELECT * INTO STRICT le FROM public.claim_leases WHERE claim_id=p_claim;
 IF b.ngo_id IS DISTINCT FROM ngo OR t.ngo_user_id IS DISTINCT FROM ngo OR c.ngo_user_id IS DISTINCT FROM ngo
  OR b.closed_at IS NOT NULL
  OR (SELECT route_status FROM public.pickup_routes WHERE route_id=i.route_id) NOT IN('AUTHORISED','IN_PROGRESS')
  THEN RAISE EXCEPTION 'OWNED_STARTED_ROUTE_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM resolution_private.cases rc WHERE rc.route_id=i.route_id AND rc.status IN('AWAITING_EVIDENCE','MANUAL_REVIEW'))
  THEN RAISE EXCEPTION 'WHOLE_ROUTE_INTERRUPTION_REQUIRES_RECONCILIATION'; END IF;
 IF t.task_status NOT IN('PLANNED','CONFIRMED') OR i.consumed_at IS NOT NULL OR i.collected_at IS NOT NULL
  OR NOT EXISTS(SELECT 1 FROM public.active_task_route_assignments a WHERE a.route_id=i.route_id AND a.task_id=i.task_id)

  THEN RAISE EXCEPTION 'PICKUP_CUSTODY_REQUIRES_RECONCILIATION'; END IF;
 IF c.claim_status<>'RECONCILIATION_REQUIRED' OR le.lease_status<>'RECONCILIATION_REQUIRED'
  OR NOT EXISTS(SELECT 1 FROM public.claim_reconciliation_cases rc WHERE rc.claim_id=p_claim AND rc.case_status IN('OPEN','MANUAL_REVIEW'))
  THEN RAISE EXCEPTION 'CLAIM_RECONCILIATION_NOT_READY'; END IF;
 IF le.expires_at<=clock_timestamp() THEN why:='LEASE_EXPIRED'; ELSE why:='RECONCILIATION_REQUIRED'; END IF;
 INSERT INTO routing_private.deferred_stops(route_id,task_id,claim_id,ngo_id,request_id,reason)
 VALUES(i.route_id,i.task_id,p_claim,ngo,p_request,why);
 result:=jsonb_build_object('route_id',i.route_id,'task_id',i.task_id,'claim_id',p_claim,'status','DEFERRED','request_id',p_request);
 INSERT INTO routing_private.deferred_requests VALUES(ngo,p_request,i.route_id,i.task_id,digest,result,clock_timestamp());
 INSERT INTO public.audit_events(actor_user_id,actor_role,entity_type,entity_id,event_type,request_id,claim_id,lease_id,outcome,details)
 VALUES(ngo,'NGO','ROUTE',i.route_id,'DEFER_PICKUP_RECONCILIATION',p_request,p_claim,le.lease_id,'SUCCESS',jsonb_build_object('task_id',i.task_id,'claim_id',p_claim,'reason',why,'released',false,'reassigned',false));
 RETURN result;
END

DECLARE ngo uuid:=auth.uid(); r routing_private.mixed_route_closures%rowtype;
BEGIN
 IF ngo IS NULL OR p_request IS NULL THEN RAISE EXCEPTION 'AUTHENTICATION_AND_REQUEST_REQUIRED'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('mixed-route-close:'||ngo::text||':'||p_request::text,0));
 SELECT * INTO r FROM routing_private.mixed_route_closures WHERE ngo_id=ngo AND request_id=p_request;
 IF NOT FOUND THEN RETURN jsonb_build_object('found',false,'request_id',p_request); END IF;
 RETURN jsonb_build_object('found',true,'request_id',p_request,'route_id',r.route_id,'result',r.result);
END

DECLARE ngo uuid:=auth.uid(); r routing_private.deferred_requests%rowtype;
BEGIN
 IF ngo IS NULL OR p_request IS NULL THEN RAISE EXCEPTION 'AUTHENTICATION_AND_REQUEST_REQUIRED'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('defer-pickup:'||ngo::text||':'||p_request::text,0));
 SELECT * INTO r FROM routing_private.deferred_requests WHERE ngo_id=ngo AND request_id=p_request;
 IF NOT FOUND THEN RETURN jsonb_build_object('found',false,'request_id',p_request); END IF;
 RETURN jsonb_build_object('found',true,'request_id',p_request,'route_id',r.route_id,'task_id',r.task_id,'result',r.result);
END

DECLARE b routing_private.bindings%rowtype; ids uuid[];
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'READ_COMMITTED_REQUIRED';
 END IF;
 SELECT * INTO STRICT b FROM routing_private.bindings WHERE route_id=p_route;
 PERFORM 1 FROM public.ngo_profiles WHERE user_id=b.ngo_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ROUTE_NGO_REQUIRED'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('routing-ngo:'||b.ngo_id::text,0));
 SELECT array_agg(task_id ORDER BY task_id) INTO ids
   FROM routing_private.items WHERE route_id=p_route;
 PERFORM routing_private.lock_sources(ids);
 PERFORM 1 FROM public.vehicles WHERE vehicle_id=b.vehicle_id FOR UPDATE;
 PERFORM 1 FROM public.pickup_routes WHERE route_id=p_route FOR UPDATE;
 PERFORM 1 FROM public.pickup_tasks WHERE task_id=ANY(ids) ORDER BY task_id FOR UPDATE;
 SELECT * INTO STRICT b FROM routing_private.bindings WHERE route_id=p_route FOR UPDATE;
 RETURN b;
END

DECLARE i routing_private.items%rowtype; r public.pickup_routes%rowtype;
        next_id uuid; req uuid:=gen_random_uuid();
BEGIN
 SELECT * INTO i FROM routing_private.items
 WHERE route_id=p_route AND task_id=p_task AND released_at IS NULL FOR UPDATE;
 IF NOT FOUND OR i.consumed_at IS NOT NULL OR i.collected_at IS NOT NULL THEN RETURN false; END IF;
 SELECT * INTO r FROM public.pickup_routes WHERE route_id=p_route;
 IF NOT FOUND OR r.route_status NOT IN('AUTHORISED','IN_PROGRESS') THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM resolution_private.cases c
   WHERE c.route_id=p_route AND c.status IN('AWAITING_EVIDENCE','MANUAL_REVIEW')) THEN
  RETURN false; -- retain the legacy whole-route hold until authorized resolution
 END IF;
 IF EXISTS(SELECT 1 FROM routing_private.deferred_stops d
   WHERE d.route_id=p_route AND d.task_id=p_task) THEN RETURN false; END IF;
 SELECT x.task_id INTO next_id FROM routing_private.items x
 JOIN public.pickup_tasks t USING(task_id)
 WHERE x.route_id=p_route AND x.released_at IS NULL AND x.collected_at IS NULL
  AND x.task_id<>p_task
  AND t.task_status<>'DISPATCHED'
  AND NOT EXISTS(SELECT 1 FROM routing_private.deferred_stops d
    WHERE d.route_id=x.route_id AND d.task_id=x.task_id AND d.status='DEFERRED')
 ORDER BY x.ordinal LIMIT 1;
 IF next_id IS NULL OR EXISTS(
   SELECT 1 FROM routing_private.items x
   JOIN public.pickup_tasks t USING(task_id)
   WHERE x.route_id=p_route AND x.task_id<>p_task
     AND x.released_at IS NULL AND t.task_status='DISPATCHED'
 ) OR EXISTS(
   SELECT 1 FROM routing_private.items x
   JOIN public.pickup_tasks t USING(task_id)
   JOIN public.donation_claims c USING(claim_id)
   JOIN public.claim_leases le USING(claim_id)
   WHERE x.route_id=p_route AND x.task_id<>p_task
     AND x.released_at IS NULL AND x.consumed_at IS NULL AND x.collected_at IS NULL
     AND t.task_status='PLANNED' AND c.claim_status='ACTIVE'
     AND le.lease_status='ACTIVE' AND le.expires_at<=clock_timestamp()
 ) THEN
  -- A different in-progress pickup makes check_remaining report
  -- PREVIOUS_PICKUP_UNRESOLVED; another expired, unstarted active stop also
  -- makes route feasibility fail on its lease. Neither is evidence that this
  -- PLANNED target was collected. Detach this claim independently; route start
  -- will revalidate feasibility after other dispatches finish; recovery
  -- handles each other expired stop, and check_remaining will revalidate
  -- the resulting route before any later pickup starts.
  INSERT INTO routing_private.deferred_stops(route_id,task_id,claim_id,ngo_id,request_id,reason)
  VALUES(p_route,p_task,p_claim,p_ngo,req,'LEASE_EXPIRED');
 ELSE
  -- Catch only the route-feasibility rejection. P0001 raised by the deferral
  -- insert, guards, or any later statement must abort rather than be treated
  -- as an ordinary infeasible route. The insert is inside this subtransaction
  -- so an expected feasibility rejection leaves no partial deferred-stop row.
  BEGIN
   INSERT INTO routing_private.deferred_stops(route_id,task_id,claim_id,ngo_id,request_id,reason)
   VALUES(p_route,p_task,p_claim,p_ngo,req,'LEASE_EXPIRED');
   PERFORM routing_private.check_remaining(p_route,next_id,clock_timestamp());
  EXCEPTION WHEN SQLSTATE 'P0001' THEN
   IF SQLERRM NOT IN (
     'ROUTE_BINDING_DRIFT','DISPATCH_AUTHORITY_STALE',
     'WHOLE_ROUTE_INTERRUPTION_REQUIRES_RECONCILIATION',
     'BEFORE_AUTHORIZED_DEPARTURE','PREVIOUS_PICKUP_UNRESOLVED',
     'STOP_ORDER_REQUIRED','DISPATCH_SOURCE_STALE',
     'DISPATCH_WINDOW_OR_LEASE_EXPIRED','REMAINING_ROUTE_INFEASIBLE'
   ) THEN RAISE; END IF;
   RETURN false;
  END;
 END IF;
 INSERT INTO routing_private.deferred_release_permits(task_id,transaction_id)
 VALUES(p_task,pg_current_xact_id()) ON CONFLICT DO NOTHING;
 RETURN true;
END
